INSERT INTO movies (id, title, year, director, overview, poster_path, backdrop_path) VALUES
('969681', 'Spider-Man: Brand New Day', 2026, 'Destin Daniel Cretton', 'Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.', '/iPOn6DinuVyLY17YM9mKuPofV08.jpg', '/qeQJx07rK2xm8SD2sJxFKhE7gs0.jpg'),
('1368337', 'The Odyssey', 2026, 'Christopher Nolan', 'Odysseus, the legendary King of Ithaca, embarks on a long and perilous journey home following the Trojan War. Throughout his voyage, he is forced to confront the whims of gods, mythological monsters, and trials that stretch both his cunning and his humanity to the breaking point.', '/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg', '/r57L2UBLPKcHdZQYg8tagv9XqK2.jpg'),
('634649', 'Spider-Man: No Way Home', 2021, 'Jon Watts', 'Peter Parker is unmasked and no longer able to separate his normal life from the high-stakes of being a super-hero. When he asks for help from Doctor Strange the stakes become even more dangerous, forcing him to discover what it truly means to be Spider-Man.', '/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', '/uyrOU4BDm2kbVxFsMiDFIHDhc4d.jpg'),
('1315772', 'Minions & Monsters', 2026, 'Pierre Coffin', 'This is the rambunctious, ridiculous and totally true story of how the Minions conquered Hollywood, became movie stars, lost everything, unleashed monsters onto the world and then banded together to try and save the planet from the mayhem they had just created.', '/aTmwK4yKzM52spczHFeuWldfzo7.jpg', '/kkcwhgSFd81QDlXo8ytrpHPQjhy.jpg'),
('1284041', 'The Last House', 2026, 'Louis Leterrier', 'A family suddenly sealed inside their home must work together to survive against dwindling resources and the ominous threat keeping them trapped.', '/6JU7E8Vv2M11egkctWVOScxWR75.jpg', '/1RhfevWmWCVHtEqxWBEjPOC5KG1.jpg'),
('1339713', 'Obsession', 2026, 'Curry Barker', 'After breaking the mysterious "One Wish Willow" to win his crush''s heart, a hopeless romantic finds himself getting exactly what he asked for but soon discovers that some desires come at a dark, sinister price.', '/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', '/rZfmzpixLKLR3Hg2u0WgC7XLFl8.jpg'),
('1375646', 'Colony', 2026, 'Yeon Sang-ho', 'Professor Se-jeong is thrust into a bloody nightmare when a rapidly mutating virus is released during a biotech conference causing authorities to seal the facility. Trapped inside with no escape, Se-jeong along with a small group of survivors must fight to stay alive while the infected undergo horrific transformations.', '/tN799oUR0f1gUKDYdMNrDaY7I51.jpg', '/84FEpVVbSKYvKXDZJDZXOKBxCEm.jpg'),
('1084244', 'Toy Story 5', 2026, 'Andrew Stanton', 'When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.', '/sfQtVlIHljToOwYjhe21KPGzZWK.jpg', '/8sSKdEmlmqF4kJUd28SqthXC4yZ.jpg'),
('1212763', 'Evil Dead Burn', 2026, 'Sébastien Vaniček', 'After her husband''s abrupt death, Alice seeks solace with his remaining family — descendants of a leading researcher on demonic possession. As her in-laws transform one by one into creatures that feed on fear, she comes to discover that the vows she took in life survive even in death.', '/uRxrNXQWkHoENm3nwVOZDYSCx2F.jpg', '/o0jkkpcN81QqSl8DMLScBCXyUH9.jpg'),
('1275779', 'Disclosure Day', 2026, 'Steven Spielberg', 'A cybersecurity expert becomes a whistleblower after uncovering secrets about aliens, putting him on the run from a corporation. Meanwhile, a meteorologist experiencing strange phenomena joins forces with him to prove there''s life beyond our understanding.', '/AnJ8IQJI23hNpYXVNaythu061Ru.jpg', '/flxau5Iu7bChQHsESqvGZ3FQRaI.jpg'),
('1081003', 'Supergirl', 2026, 'Craig Gillespie', 'When an unexpected and ruthless adversary strikes too close to home, Kara Zor-El, aka Supergirl, reluctantly joins forces with an unlikely companion on an epic, interstellar journey of vengeance and justice.', '/1QCWdqzTfh2x9UylVpspIU6QTuM.jpg', '/54KIfdTEzOliHDKx0OkzYGqAICx.jpg'),
('315635', 'Spider-Man: Homecoming', 2017, 'Jon Watts', 'Following the events of Captain America: Civil War, Peter Parker, with the help of his mentor Tony Stark, tries to balance his life as an ordinary high school student in Queens, New York City, with fighting crime as his superhero alter ego Spider-Man as a new threat, the Vulture, emerges.', '/c24sv2weTHPsmDa7jEMN0m2P3RT.jpg', '/fn4n6uOYcB6Uh89nbNPoU2w80RV.jpg'),
('1083381', 'Backrooms', 2026, 'Kane Parsons', 'A strange doorway appears in the basement of a furniture showroom.', '/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', '/dqmMWNWfLnExDRpMtIMqI97GQFR.jpg'),
('1273221', 'Scary Movie', 2026, 'Michael Tiddes', 'Twenty-six years after outrunning a suspiciously familiar masked killer, the Core Four are back in the killer''s crosshairs and no horror movie IP is safe.', '/znHT8peERZRWG1ME3r0Db0EV8k8.jpg', '/xWBiXclrRmTggQHMRsIn84YHavs.jpg'),
('1481343', 'The Devil''s Mouth', 2026, 'Jeff Wadlow', 'A group of college friends'' Thailand adventure turns deadly when they become trapped in submerged caves with a dangerous predator. As oxygen runs low, past conflicts emerge in their desperate fight for survival.', '/lH8k9uCWYn2b2gsYleqYBDPbWa8.jpg', '/4wmvU2Px3C8v3qqyNpBmgJrWQEx.jpg'),
('687163', 'Project Hail Mary', 2026, 'Phil Lord, Christopher Miller', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', '/yihdXomYb5kTeSivtFndMy5iDmf.jpg', '/8Tfys3mDZVp4tNoH2ktm06a0Tau.jpg'),
('980431', 'Avatar Aang: The Last Airbender', 2026, 'Lauren Montgomery', 'Avatar Aang, the world''s last Airbender, learns of an ancient power that could save his culture from extinction. With the help of his friends, he embarks on a global quest to find it before it falls into the wrong hands and threatens to upend the peace they sacrificed everything to achieve.', '/3sgnSfNT27Bx5O5ukr7B26mhEQq.jpg', '/ezbrL1dMymKQZw7mDEWa2ZTzN7d.jpg'),
('557', 'Spider-Man', 2002, 'Sam Raimi', 'After being bitten by a genetically altered spider at Oscorp, nerdy but endearing high school student Peter Parker is endowed with amazing powers to become the superhero known as Spider-Man.', '/or6XJBVpcEbIkma0V9zshnbEtx4.jpg', '/zQ8AxTPiCiS5nnwXpwTBPBHSaa5.jpg'),
('454639', 'Masters of the Universe', 2026, 'Travis Knight', 'After being separated for 15 years, the Sword of Power leads Prince Adam back to Eternia, where he discovers his home shattered under the fiendish rule of Skeletor. To save his family and his world, Adam must join forces with his closest allies, Teela and Duncan/Man-At-Arms, and embrace his true destiny as He-Man — the most powerful man in the universe.', '/oRuyGUHdoaQxWP3SDfafGkStxTC.jpg', '/yQIdU11DYQQp0neGtGtGxbGfRer.jpg'),
('1564614', 'Leviticus', 2026, 'Adrian Chiarella', 'Two teenage boys must escape a violent entity that takes the form of the person they desire most:  each other.', '/gnAsZvBygplNpp8PtjoTEYv3VPB.jpg', '/7y8zWGEjs7tresw4Hzkkf4TdkcL.jpg'),
('1311031', 'Demon Slayer: Kimetsu no Yaiba Infinity Castle', 2025, 'Haruo Sotozaki', 'The Demon Slayer Corps are drawn into the Infinity Castle, where Tanjiro, Nezuko, and the Hashira face terrifying Upper Rank demons in a desperate fight as the final battle against Muzan Kibutsuji begins.', '/fWVSwgjpT2D78VUh6X8UBd2rorW.jpg', '/1RgPyOhN4DRs225BGTlHJqCudII.jpg'),
('1280738', 'The Furious', 2026, 'Kenji Tanigaki', 'After a criminal network kidnaps Wang Wei''s daughter and the corrupt police refuse to assist him, Wei sets out on his own to locate her. Navin, a tenacious journalist whose wife has mysteriously vanished, is his only ally. In this explosive martial arts showdown, the unlikely duo fights the kidnappers ruthlessly driven by a furious vengeance.', '/zP19YO60jwEsfKd5Qf1UvA5uJu8.jpg', '/9XwQphZxNJgGASfjL58mhIkJJpf.jpg'),
('936075', 'Michael', 2026, 'Antoine Fuqua', 'The story of Michael Jackson, one of the most influential artists the world has ever known, and his life beyond the music. His journey from the discovery of his extraordinary talent as the lead of the Jackson Five, to the visionary artist whose creative ambition fueled a relentless pursuit to become the biggest entertainer in the world, highlighting both his life off-stage and some of the most iconic performances from his early solo career.', '/2AvgnCwCakNiJqWZqaQhdGjWNey.jpg', '/ufSwlnECLoUbBjPrFqEQcWBzHwc.jpg'),
('1314481', 'The Devil Wears Prada 2', 2026, 'David Frankel', 'Andy Sachs returns to Runway as Miranda Priestly navigates a new media landscape and Runway''s position within. The duo reconnect with former assistant Emily Charlton, now the head of a luxury brand that possesses funding which could ensure Runway''s survival.', '/xTI42pmsP5EDnvsNJPEDubwWBQO.jpg', '/Af907x5h9W1wVis8XrSd7ynTWuy.jpg'),
('1930', 'The Amazing Spider-Man', 2012, 'Marc Webb', 'A teenage Peter Parker grapples with both high school and amazing super-human crises as his alter-ego Spider-Man.', '/jexoNYnPd6vVrmygwF6QZmWPFdu.jpg', '/HVcza6tJtWFrLriuh3Ano4Vt46.jpg'),
('429617', 'Spider-Man: Far From Home', 2019, 'Jon Watts', 'Peter Parker and his friends go on a summer trip to Europe. However, they will hardly be able to rest - Peter will have to agree to help Nick Fury uncover the mystery of creatures that cause natural disasters and destruction throughout the continent.', '/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg', '/vamhMTvh9m9zFHDoR0v1nRtf6T4.jpg'),
('1127384', 'Deep Water', 2026, 'Renny Harlin', 'A group of international passengers on a flight from Los Angeles to Shanghai is forced to make an emergency landing in shark-infested waters. The terrified group is forced to work together and overcome their differences if they hope to escape their sinking plane and the frenzy of sharks drawn to the wreckage.', '/kjcuS7xaRyqRjVaVcH4t0qHshuX.jpg', '/szKv713FcUXx6hcfdY369vtkmzr.jpg'),
('278', 'The Shawshank Redemption', 1994, 'Frank Darabont', 'Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.', '/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg', '/zfbjgQE1uSd9wiPTX4VzsLi0rGG.jpg'),
('24428', 'The Avengers', 2012, 'Joss Whedon', 'When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!', '/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg', '/9BBTo63ANSmhC4e6r62OJFuK2GL.jpg'),
('1084242', 'Zootopia 2', 2025, 'Jared Bush, Byron Howard', 'After cracking the biggest case in Zootopia''s history, rookie cops Judy Hopps and Nick Wilde find themselves on the twisting trail of a great mystery when Gary De''Snake arrives and turns the animal metropolis upside down. To crack the case, Judy and Nick must go undercover to unexpected new parts of town, where their growing partnership is tested like never before.', '/oJ7g2CifqpStmoYQyaLQgEU32qO.jpg', '/lgotja3xMoJZbynwHfcQcJAEMWH.jpg'),
('299536', 'Avengers: Infinity War', 2018, 'Joe Russo, Anthony Russo', 'As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment - the fate of Earth and existence itself has never been more uncertain.', '/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', '/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg'),
('755898', 'War of the Worlds', 2025, 'Rich Lee', 'Will Radford is a top analyst for Homeland Security who tracks potential threats through a mass surveillance program, until one day an attack by an unknown entity leads him to question whether the government is hiding something from him... and from the rest of the world.', '/yvirUYrva23IudARHn3mMGVxWqM.jpg', '/iZLqwEwUViJdSkGVjePGhxYzbDb.jpg'),
('1439930', 'The Punisher: One Last Kill', 2026, 'Reinaldo Marcus Green', 'As Frank Castle searches for meaning beyond revenge, an unexpected force pulls him back into the fight.', '/qQclTgLMDvGBuUBFGHRipxkEwWR.jpg', '/qO55CD8tgVL1T4WKn6zYFFiD6lL.jpg'),
('1226863', 'The Super Mario Galaxy Movie', 2026, 'Michael Jelenic, Aaron Horvath', 'Having thwarted Bowser''s previous plot to marry Princess Peach, Mario and Luigi now face a fresh threat in Bowser Jr., who is determined to liberate his father from captivity and restore the family legacy. Alongside companions new and old, the brothers travel across the stars to stop the young heir''s crusade.', '/eJGWx219ZcEMVQJhAgMiqo8tYY.jpg', '/kxQiIJ4gVcD3K6o14MJ72p5yRcE.jpg'),
('931285', 'Mortal Kombat II', 2026, 'Simon McQuoid', 'The fan favorite champions—now joined by Johnny Cage himself—are pitted against one another in the ultimate, no-holds barred, gory battle to defeat the dark rule of Shao Kahn that threatens the very existence of the Earthrealm and its defenders.', '/hwRdDFIhaEmpRgoki805YvyyjZf.jpg', '/4EAAwpylq313qrDqpCxulUrXBNF.jpg'),
('83533', 'Avatar: Fire and Ash', 2025, 'James Cameron', 'In the wake of the devastating war against the RDA and the loss of their eldest son, Jake Sully and Neytiri face a new threat on Pandora: the Ash People, a violent and power-hungry Na''vi tribe led by the ruthless Varang. Jake''s family must fight for their survival and the future of Pandora in a conflict that pushes them to their emotional and physical limits.', '/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg', '/sdZSjtGUTSN8B3al5o0f2WoQfQQ.jpg'),
('822119', 'Captain America: Brave New World', 2025, 'Julius Onah', 'After meeting with newly elected U.S. President Thaddeus Ross, Sam finds himself in the middle of an international incident. He must discover the reason behind a nefarious global plot before the true mastermind has the entire world seeing red.', '/pzIddUEMWhWzfvLI3TwxUG2wGoi.jpg', '/ce3prrjh9ZehEl5JinNqr4jIeaB.jpg'),
('1228710', 'The Mandalorian and Grogu', 2026, 'Jon Favreau', 'The evil Empire has fallen, and Imperial warlords remain scattered throughout the galaxy. As the fledgling New Republic works to protect everything the Rebellion fought for, they have enlisted the help of legendary Mandalorian bounty hunter Din Djarin and his young apprentice Grogu.', '/7GV5rrUJf0BRUhoh2cyFoeNthlQ.jpg', '/MJcERawyqGqJdPsOBc0C449hQ9.jpg'),
('559', 'Spider-Man 3', 2007, 'Sam Raimi', 'The seemingly invincible Spider-Man goes up against an all-new crop of villains—including the shape-shifting Sandman. While Spider-Man’s superpowers are altered by an alien organism, his alter ego, Peter Parker, deals with nemesis Eddie Brock and also gets caught up in a love triangle.', '/sJMTTGjtjvrMZ7G0oP9D13wNUum.jpg', '/FfAU0PUs8AJkMU2VbkVNFtRXR4.jpg'),
('569094', 'Spider-Man: Across the Spider-Verse', 2023, 'Justin K. Thompson, Kemp Powers, Joaquim Dos Santos', 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse, where he encounters the Spider Society, a team of Spider-People charged with protecting the Multiverse''s very existence. But when the heroes clash on how to handle a new threat, Miles finds himself pitted against the other Spiders and must set out on his own to save those he loves most.', '/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', '/kVd3a9YeLGkoeR50jGEXM6EqseS.jpg'),
('102382', 'The Amazing Spider-Man 2', 2014, 'Marc Webb', 'For Peter Parker, life is busy. Between taking out the bad guys as Spider-Man and spending time with the person he loves, Gwen Stacy, high school graduation cannot come quickly enough. Peter has not forgotten about the promise he made to Gwen’s father to protect her by staying away, but that is a promise he cannot keep. Things will change for Peter when a new villain, Electro, emerges, an old friend, Harry Osborn, returns, and Peter uncovers new clues about his past.', '/dGjoPttcbKR5VWg1jQuNFB247KL.jpg', '/k0hlAzTryCYX1O1LyC6P8tAa8s0.jpg'),
('1419406', 'The Shadow''s Edge', 2025, 'Larry Yang', 'Macau Police brings the tracking expert police officer out of retirement to help catch a dangerous group of professional thieves.', '/cHKo3m8N1fwvEy2ZEr0xGmmMODV.jpg', '/4BtL2vvEufDXDP4u6xQjjQ1Y2aT.jpg'),
('299534', 'Avengers: Endgame', 2019, 'Joe Russo, Anthony Russo', 'After the devastating events of Avengers: Infinity War, the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos'' actions and restore order to the universe once and for all, no matter what consequences may be in store.', '/ulzhLuWrPK07P1YkdWQLZnQh1JL.jpg', '/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg'),
('27205', 'Inception', 2010, 'Christopher Nolan', 'Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person''s idea into a target''s subconscious.', '/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg', '/8ZTVqvKDQ8emSGUEMjsS4yHAwrp.jpg'),
('1290821', 'Shelter', 2026, 'Ric Roman Waugh', 'A man living in self-imposed exile on a remote island rescues a young girl from a violent storm, setting off a chain of events that forces him out of seclusion to protect her from enemies tied to his past.', '/buPFnHZ3xQy6vZEHxbHgL1Pc6CR.jpg', '/nHxWyy18SvAZ8jJeemtS8k1UNjM.jpg'),
('155', 'The Dark Knight', 2008, 'Christopher Nolan', 'Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.', '/qJ2tW6WMUDux911r6m7haRef0WH.jpg', '/cfT29Im5VDvjE0RpyKOSdCKZal7.jpg'),
('1327819', 'Hoppers', 2026, 'Daniel Chong', 'Scientists have discovered how to ''hop'' human consciousness into lifelike robotic animals, allowing people to communicate with animals as animals. Animal lover Mabel seizes an opportunity to use the technology, uncovering mysteries within the animal world beyond anything she could have imagined.', '/xjtWQ2CL1mpmMNwuU5HeS4Iuwuu.jpg', '/3Jj0A10NVu2dWnoEL5t5oT79L1Y.jpg'),
('238', 'The Godfather', 1972, 'Francis Ford Coppola', 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.', '/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', '/tSPT36ZKlP2WVHJLM4cQPLSzv3b.jpg'),
('324857', 'Spider-Man: Into the Spider-Verse', 2018, 'Bob Persichetti, Peter Ramsey, Rodney Rothman', 'Struggling to find his place in the world while juggling school and family, Brooklyn teenager Miles Morales is unexpectedly bitten by a radioactive spider and develops unfathomable powers just like the one and only Spider-Man. While wrestling with the implications of his new abilities, Miles discovers a super collider created by the madman Wilson "Kingpin" Fisk, causing others from across the Spider-Verse to be inadvertently transported to his dimension.', '/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', '/8mnXR9rey5uQ08rZAvzojKWbDQS.jpg'),
('157336', 'Interstellar', 2014, 'Christopher Nolan', 'The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.', '/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg', '/5XNQBqnBwPA9yT0jZ0p3s8bbLh0.jpg'),
('1184918', 'The Wild Robot', 2024, 'Chris Sanders', 'After a shipwreck, an intelligent robot called Roz is stranded on an uninhabited island. To survive the harsh environment, Roz bonds with the island''s animals and cares for an orphaned baby goose.', '/wTnV3PCVW5O92JMrFvvrRcV39RU.jpg', '/mQZJoIhTEkNhCYAqcHrQqhENLdu.jpg'),
('1368166', 'The Housemaid', 2025, 'Paul Feig', 'Trying to escape her past, Millie Calloway accepts a job as a live-in housemaid for the wealthy Nina and Andrew Winchester. But what begins as a dream job quickly unravels into something far more dangerous—a sexy, seductive game of secrets, scandal, and power.', '/cWsBscZzwu5brg9YjNkGewRUvJX.jpg', '/zTnAnYIn0Iv3cn0ZHlzLhou3ybm.jpg'),
('533535', 'Deadpool & Wolverine', 2024, 'Shawn Levy', 'A listless Wade Wilson toils away in civilian life with his days as the morally flexible mercenary, Deadpool, behind him. But when his homeworld faces an existential threat, Wade must reluctantly suit-up again with an even more reluctant Wolverine.', '/8cdWjvZQUExUUTzyp4t6EDMubfO.jpg', '/by8z9Fe8y7p4jo2YlW2SZDnptyT.jpg'),
('271110', 'Captain America: Civil War', 2016, 'Joe Russo, Anthony Russo', 'Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.', '/rAGiXaUfPzY7CDEyNKUofk3Kw2e.jpg', '/wdwcOBMkt3zmPQuEMxB3FUtMio2.jpg'),
('1304313', 'Lee Cronin''s The Mummy', 2026, 'Lee Cronin', 'The young daughter of a journalist disappears into the desert without a trace—eight years later, the broken family is shocked when she is returned to them, as what should be a joyful reunion turns into a living nightmare.', '/1q308iixueCU4pFtSYugNOevtNx.jpg', '/xugEpZk9YQ0DIz1aFvH5HGkqpZK.jpg'),
('617126', 'The Fantastic 4: First Steps', 2025, 'Matt Shakman', 'Against the vibrant backdrop of a 1960s-inspired, retro-futuristic world, Marvel''s First Family is forced to balance their roles as heroes with the strength of their family bond, while defending Earth from a ravenous space god called Galactus and his enigmatic Herald, Silver Surfer.', '/nf5qaSEvyYSNeFH0YhSs5EsBLX9.jpg', '/s94NjfKkcSczZ1FembwmQZwsuwY.jpg'),
('803796', 'KPop Demon Hunters', 2025, 'Chris Appelhans, Maggie Kang', 'When K-pop superstars Rumi, Mira and Zoey aren''t selling out stadiums, they''re using their secret powers to protect their fans from supernatural threats.', '/zT7Lhw3BhJbMkRqm9Zlx2YGMsY0.jpg', '/w3Bi0wygeFQctn6AqFTwhGNXRwL.jpg'),
('1007757', 'Swapped', 2026, 'Nathan Greno', 'A small woodland creature and a majestic bird, two natural sworn enemies of the Valley, magically trade places and set off on an adventure of a lifetime to switch back. Their journey soon uncovers a greater threat—one that could endanger not only their species, but the entire valley they call home.', '/tHhxWxge06goXU6ZQH1hj7vK8Hd.jpg', '/zMwhWailP1WY7sb6AoE6b8ugoy.jpg'),
('122', 'The Lord of the Rings: The Return of the King', 2003, 'Peter Jackson', 'As armies mass for a final battle that will decide the fate of the world--and powerful, ancient forces of Light and Dark compete to determine the outcome--one member of the Fellowship of the Ring is revealed as the noble heir to the throne of the Kings of Men. Yet, the sole hope for triumph over evil lies with a brave hobbit, Frodo, who, accompanied by his loyal friend Sam and the hideous, wretched Gollum, ventures deep into the very dark heart of Mordor on his seemingly impossible quest to destroy the Ring of Power.​', '/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', '/2u7zbn8EudG6kLlBzUYqP8RyFU4.jpg'),
('1234821', 'Jurassic World Rebirth', 2025, 'Gareth Edwards', 'Five years after the events of Jurassic World Dominion, covert operations expert Zora Bennett is contracted to lead a skilled team on a top-secret mission to secure genetic material from the world''s three most massive dinosaurs. When Zora''s operation intersects with a civilian family whose boating expedition was capsized, they all find themselves stranded on an island where they come face-to-face with a sinister, shocking discovery that''s been hidden from the world for decades.', '/1RICxzeoNCAO5NpcRMIgg1XT6fm.jpg', '/zNriRTr0kWwyaXPzdg1EIxf0BWk.jpg'),
('652', 'Troy', 2004, 'Wolfgang Petersen', 'In year 1250 B.C. during the late Bronze age, two emerging nations begin to clash. Paris, the Trojan prince, convinces Helen, Queen of Sparta, to leave her husband Menelaus, and sail with him back to Troy. After Menelaus finds out that his wife was taken by the Trojans, he asks his brother Agamemnon to help him get her back. Agamemnon sees this as an opportunity for power. They set off with 1,000 ships holding 50,000 Greeks to Troy.', '/a07wLy4ONfpsjnBqMwhlWTJTcm.jpg', '/cu3lhUReOdqFAo5K1jesoftwiBj.jpg'),
('361743', 'Top Gun: Maverick', 2022, 'Joseph Kosinski', 'After more than thirty years of service as one of the Navy’s top aviators, and dodging the advancement in rank that would ground him, Pete “Maverick” Mitchell finds himself training a detachment of TOP GUN graduates for a specialized mission the likes of which no living pilot has ever seen.', '/n0YuM4f5lvGAP6MAW2kBIzugXnc.jpg', '/AaV1YIdWKnjAIAOe8UUKBFm327v.jpg'),
('603', 'The Matrix', 1999, 'Lana Wachowski, Lilly Wachowski', 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.', '/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg', '/tlm8UkiQsitc8rSuIAscQDCnP8d.jpg'),
('671', 'Harry Potter and the Philosopher''s Stone', 2001, 'Chris Columbus', 'Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard—with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths—and about the villain who''s to blame.', '/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg', '/1XAC6RPT01UX9EQGy2JVn5c8pgy.jpg'),
('986056', 'Thunderbolts*', 2025, 'Jake Schreier', 'After finding themselves ensnared in a death trap, seven disillusioned castoffs must embark on a dangerous mission that will force them to confront the darkest corners of their pasts.', '/hqcexYHbiTBfDIdDWxrxPtVndBX.jpg', '/rthMuZfFv4fqEU4JVbgSW9wQ8rs.jpg'),
('872585', 'Oppenheimer', 2023, 'Christopher Nolan', 'The story of J. Robert Oppenheimer''s role in the development of the atomic bomb during World War II.', '/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg', '/neeNHeXjMF5fXoCJRsOmkNGC7q.jpg'),
('693134', 'Dune: Part Two', 2024, 'Denis Villeneuve', 'Follow the mythic journey of Paul Atreides as he unites with Chani and the Fremen while on a path of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the known universe, Paul endeavors to prevent a terrible future only he can foresee.', '/6izwz7rsy95ARzTR3poZ8H6c5pp.jpg', '/eZ239CUp1d6OryZEBPnO2n87gMG.jpg'),
('840464', 'Greenland 2: Migration', 2026, 'Ric Roman Waugh', 'Having found the safety of the Greenland bunker after the comet Clarke decimated the Earth, the Garrity family must now risk everything to embark on a perilous journey across the wasteland of Europe to find a new home.', '/z2tqCJLsw6uEJ8nJV8BsQXGa3dr.jpg', '/cLFbDVfhllIMybpo2fkGNzehiQG.jpg'),
('1726', 'Iron Man', 2008, 'Jon Favreau', 'After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.', '/78lPtwv72eTNqFW9COBYI0dWDJa.jpg', '/cKvDv2LpwVEqbdXWoQl4XgGN6le.jpg'),
('1413976', 'Citizen Vigilante', 2026, 'Uwe Boll', 'A man takes justice into his own hands, hunting down criminals. His vigilante crusade makes him a social media star but puts him at odds with the local police chief.', '/6LmJD3Wohe0g4U62wgi7RyJqfE4.jpg', '/qJ2KSHJhlFvASBMLbGuP7OFMaFg.jpg'),
('550', 'Fight Club', 1999, 'David Fincher', 'A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground "fight clubs" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.', '/jSziioSwPVrOy9Yow3XhWIBDjq1.jpg', '/c6OLXfKAk5BKeR6broC8pYiCquX.jpg'),
('284053', 'Thor: Ragnarok', 2017, 'Taika Waititi', 'Thor is imprisoned on the other side of the universe and finds himself in a race against time to get back to Asgard to stop Ragnarok, the destruction of his home-world and the end of Asgardian civilization, at the hands of a powerful new threat, the ruthless Hela.', '/rzRwTcFvttcN1ZpX2xv4j3tSdJu.jpg', '/vLmHH8jAy8Jq8uBsLucd3592WGh.jpg'),
('949838', '72 HOURS', 2026, 'Tim Story', 'To save his career, a 40-year-old ad exec joins a crew of twentysomethings for a wild Miami bachelor party after they mistakenly add him to a group chat.', '/9Bu1PW2R1XayqRqnl0aDOgMcrdS.jpg', '/hL5EIk48251OXlbIbRJq3yaBHk8.jpg'),
('120', 'The Lord of the Rings: The Fellowship of the Ring', 2001, 'Peter Jackson', 'Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.', '/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', '/mWDdRXTivGE7aaY2vo1Ie0PfCX5.jpg'),
('1122573', 'In the Grey', 2026, 'Guy Ritchie', 'A covert team of elite operatives are living in the shadows. When a ruthless despot steals a billion-dollar fortune, they''re sent to take it back—an impossible heist that erupts into a deadly game of strategy, deception and survival.', '/dQgIcW6Th08kMRf2HBoYWoFE6OD.jpg', '/qcIKxhqGMIj8uujsSoSMZWr8QqU.jpg'),
('1242898', 'Predator: Badlands', 2025, 'Dan Trachtenberg', 'Cast out from his clan, a young Predator finds an unlikely ally in a damaged android and embarks on a treacherous journey in search of the ultimate adversary.', '/pHpq9yNUIo6aDoCXEBzjSolywgz.jpg', '/82lM4GJ9uuNvNDOEpxFy77uv4Ak.jpg'),
('1724', 'The Incredible Hulk', 2008, 'Louis Leterrier', 'Scientist Bruce Banner scours the planet for an antidote to the unbridled force of rage within him: the Hulk. But when the military masterminds who dream of exploiting his powers force him back to civilization, he finds himself coming face to face with a new, deadly foe.', '/gKzYx79y0AQTL4UAk1cBQJ3nvrm.jpg', '/jPu8yiadqgzwFPGKJmGo637ASVP.jpg'),
('453395', 'Doctor Strange in the Multiverse of Madness', 2022, 'Sam Raimi', 'Doctor Strange, with the help of mystical allies both old and new, traverses the mind-bending and dangerous alternate realities of the Multiverse to confront a mysterious new adversary.', '/ddJcSKbcp4rKZTmuyWaMhuwcfMz.jpg', '/lv3TXqhpaIxkclIHbhN2MRMOemQ.jpg'),
('99861', 'Avengers: Age of Ultron', 2015, 'Joss Whedon', 'When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.', '/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg', '/kIBK5SKwgqIIuRKhhWrJn3XkbPq.jpg'),
('1272837', '28 Years Later: The Bone Temple', 2026, 'Nia DaCosta', 'Dr. Kelson finds himself in a shocking new relationship - with consequences that could change the world as they know it - and Spike''s encounter with Jimmy Crystal becomes a nightmare he can''t escape.', '/kK1BGkG3KAvWB0WMV1DfOx9yTMZ.jpg', '/hHDNOlATHhre4eZ7aYz5cdyJLik.jpg'),
('98', 'Gladiator', 2000, 'Ridley Scott', 'After the death of Emperor Marcus Aurelius, his devious son takes power and demotes Maximus, one of Rome''s most capable generals who Marcus preferred. Eventually, Maximus is forced to become a gladiator and battle to the death against other men for the amusement of paying audiences.', '/wN2xWp1eIwCKOD0BHTcErTBv1Uq.jpg', '/jhk6D8pim3yaByu1801kMoxXFaX.jpg'),
('1325734', 'The Drama', 2026, 'Kristoffer Borgli', 'A happily engaged couple is put to the test when an unexpected turn sends their wedding week off the rails.', '/rnIOUhzwJDfgQakx8EjoNyItKgs.jpg', '/1oKLEA9JOhvaBwLpqjROisvWMy7.jpg'),
('1318447', 'Apex', 2026, 'Baltasar Kormákur', 'A grieving woman pushing her limits on a solo adventure in the Australian wild is ensnared in a twisted game with a cunning killer who thinks she''s prey.', '/eTp7gSPkSF3Aw79mNx1NkBP1PZT.jpg', '/9nzfyiYbmTUXWC4B2kwjl4NAlqO.jpg'),
('105', 'Back to the Future', 1985, 'Robert Zemeckis', 'Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents'' first meeting and attracting his mother''s romantic interest. Marty must repair the damage to history by rekindling his parents'' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.', '/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg', '/5bzPWQ2dFUl2aZKkp7ILJVVkRed.jpg'),
('1301421', 'The Sheep Detectives', 2026, 'Kyle Balda', 'George Hardy is a shepherd who reads detective novels to his beloved sheep every night, assuming they can''t possibly understand. But when a mysterious incident disrupts life on the farm, the sheep realize they must become the detectives. As they follow the clues and investigate human suspects, they prove that even sheep can be brilliant crime-solvers.', '/mGWOmj2jHFol3kOGNv1EhbSDDE1.jpg', '/a8uQvrplTkhGJQog6GZ6CqF8An6.jpg'),
('967941', 'Wicked: For Good', 2025, 'Jon M. Chu', 'As an angry mob rises against the Wicked Witch, Glinda and Elphaba will need to come together one final time. With their singular friendship now the fulcrum of their futures, they will need to truly see each other, with honesty and empathy, if they are to change themselves, and all of Oz, for good.', '/si9tolnefLSUKaqQEGz1bWArOaL.jpg', '/cGbPBHKSFO7hSIjxkb3KOaGdOep.jpg'),
('1087891', 'The Amateur', 2025, 'James Hawes', 'After his life is turned upside down when his wife is killed in a London terrorist attack, a brilliant but introverted CIA decoder takes matters into his own hands when his supervisors refuse to take action.', '/SNEoUInCa5fAgwuEBMIMBGvkkh.jpg', '/aD7FXrm2GErTmzrIFBntPyhAqS9.jpg'),
('1061474', 'Superman', 2025, 'James Gunn', 'Superman, a journalist in Metropolis, embarks on a journey to reconcile his Kryptonian heritage with his human upbringing as Clark Kent.', '/ldyfo0BKmz5rWtJJKCvwaNS4cJT.jpg', '/eGX66zonvc4bXg3rM08RUxdYSDx.jpg'),
('798645', 'The Running Man', 2025, 'Edgar Wright', 'Desperate to save his sick daughter, working-class Ben Richards is convinced by The Running Man''s charming but ruthless producer to enter the deadly competition game as a last resort. But Ben''s defiance, instincts, and grit turn him into an unexpected fan favorite — and a threat to the entire system. As ratings skyrocket, so does the danger, and Ben must outwit not just the Hunters, but a nation addicted to watching him fall.', '/dKL78O9zxczVgjtNcQ9UkbYLzqX.jpg', '/aHj7d7wSLqrg5cjAcgHhiGr97Ih.jpg'),
('1265609', 'War Machine', 2026, 'Patrick Hughes', 'On one last grueling mission during Army Ranger training, a combat engineer must lead his unit in a fight against a giant otherworldly killing machine.', '/rFhKkXhk7ClU03jQ5rHIApJDwev.jpg', '/6yeVcxFR0j08vlv2OlL6zbewm4D.jpg'),
('933260', 'The Substance', 2024, 'Coralie Fargeat', 'A fading celebrity decides to use a black market drug, a cell-replicating substance that temporarily creates a younger, better version of herself.', '/uYJvxMWMb9W4zIY3cbM50sj3dpC.jpg', '/bVSOgrxasVJF6V71T7v2KfBRSzu.jpg'),
('672', 'Harry Potter and the Chamber of Secrets', 2002, 'Chris Columbus', 'Cars fly, trees fight back, and a mysterious house-elf comes to warn Harry Potter at the start of his second year at Hogwarts. Adventure and danger await when bloody writing on a wall announces: The Chamber Of Secrets Has Been Opened. To save Hogwarts will require all of Harry, Ron and Hermione''s magical abilities and courage.', '/sdEOH0992YZ0QSxgXNIGLq1ToUi.jpg', '/1stUIsjawROZxjiCMtqqXqgfZWC.jpg'),
('121', 'The Lord of the Rings: The Two Towers', 2002, 'Peter Jackson', 'Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers--Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron''s fortress at Barad-dur, deep within the dark lands of Mordor. Frodo and Sam are trekking to Mordor to destroy the One Ring of Power while Gimli, Legolas and Aragorn search for the orc-captured Merry and Pippin. All along, nefarious wizard Saruman awaits the Fellowship members at the Orthanc Tower in Isengard.', '/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', '/6G73mNyooWAEQTpckPSnFxFoNmc.jpg'),
('680', 'Pulp Fiction', 1994, 'Quentin Tarantino', 'A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.', '/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg', '/suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg'),
('496243', 'Parasite', 2019, 'Bong Joon Ho', 'All unemployed, Ki-taek''s family takes peculiar interest in the wealthy and glamorous Parks for their livelihood until they get entangled in an unexpected incident.', '/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', '/vbC0rzdrb7Ohc2TkbEbxtOABECe.jpg'),
('14836', 'Coraline', 2009, 'Henry Selick', 'Wandering her rambling old house in her boring new town, 11-year-old Coraline discovers a hidden door to a strangely idealized version of her life. In order to stay in the fantasy, she must make a frighteningly real sacrifice.', '/4jeFXQYytChdZYE9JYO7Un87IlW.jpg', '/hofnlIyF6bePkgQOpcuRWLvzf15.jpg'),
('674', 'Harry Potter and the Goblet of Fire', 2005, 'Mike Newell', 'When his name emerges from the Goblet of Fire, Harry Potter becomes a competitor in a grueling battle for glory among three wizarding schools. Signs of Voldemort''s return emerge as Harry''s friends help him prepare for the Triwizard Tournament.', '/fECBtHlr0RB3foNHDiCBXeg9Bv9.jpg', '/1OV7hau4D3rWGS5bu8sqBYeVpe.jpg'),
('911430', 'F1', 2025, 'Joseph Kosinski', 'Racing legend Sonny Hayes is coaxed out of retirement to lead a struggling Formula 1 team—and mentor a young hotshot driver—while chasing one more chance at glory.', '/9PXZIUsSDh4alB80jheWX4fhZmy.jpg', '/lkDYN0whyE82mcM20rwtwjbniKF.jpg'),
('1010581', 'My Fault', 2023, 'Domingo González', 'Noah must leave her city, boyfriend, and friends to move into William Leister''s mansion, the flashy and wealthy husband of her mother Rafaela. As a proud and independent 17 year old, Noah resists living in a mansion surrounded by luxury. However, it is there where she meets Nick, her new stepbrother, and the clash of their strong personalities becomes evident from the very beginning.', '/w46Vw536HwNnEzOa7J24YH9DPRS.jpg', '/oz4U9eA6ilYf1tyiVuGmkftdLac.jpg'),
('436969', 'The Suicide Squad', 2021, 'James Gunn', 'Supervillains Harley Quinn, Bloodsport, Peacemaker and a collection of nutty cons at Belle Reve prison join the super-secret, super-shady Task Force X as they are dropped off at the remote, enemy-infused island of Corto Maltese.', '/q61qEyssk2ku3okWICKArlAdhBn.jpg', '/jlGmlFOcfo8n5tURmhC7YVd4Iyy.jpg'),
('862', 'Toy Story', 1995, 'John Lasseter', 'Led by Woody, Andy''s toys live happily in his room until Andy''s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy''s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.', '/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg', '/3Rfvhy1Nl6sSGJwyjb0QiZzZYlB.jpg'),
('1297842', 'GOAT', 2026, 'Tyree Dillihay', 'A small goat with big dreams gets a once-in-a-lifetime shot to join the pros and play roarball, a high-intensity, co-ed, full-contact sport dominated by the fastest, fiercest animals in the world.', '/wfuqMlaExcoYiUEvKfVpUTt1v4u.jpg', '/tq3h43fZy0H80vzf47MAY7R9Mxo.jpg'),
('597', 'Titanic', 1997, 'James Cameron', '101-year-old Rose DeWitt Bukater tells the story of her life aboard the Titanic, 84 years later. A young Rose boards the ship with her mother and fiancé. Meanwhile, Jack Dawson and Fabrizio De Rossi win third-class tickets aboard the ship. Rose tells the whole story from Titanic''s departure through to its death—on its first and last voyage—on April 15, 1912.', '/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg', '/xnHVX37XZEp33hhCbYlQFq7ux1J.jpg'),
('68718', 'Django Unchained', 2012, 'Quentin Tarantino', 'With the help of a German bounty hunter, a freed slave sets out to rescue his wife from a brutal Mississippi plantation owner.', '/7oWY8VDWW7thTzWh3OKYRkWUlD5.jpg', '/2oZklIzUbvZXXzIFzv7Hi68d6xf.jpg'),
('447365', 'Guardians of the Galaxy Vol. 3', 2023, 'James Gunn', 'Peter Quill, still reeling from the loss of Gamora, must rally his team around him to defend the universe along with protecting one of their own. A mission that, if not completed successfully, could quite possibly lead to the end of the Guardians as we know them.', '/r2J02Z2OpNTctfOSN1Ydgii51I3.jpg', '/5YZbUmjbMa3ClvSW1Wj3D6XGolb.jpg'),
('354912', 'Coco', 2017, 'Lee Unkrich', 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.', '/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', '/g7CHF8gTLGooTbP4GznIGwaqAGL.jpg'),
('350', 'The Devil Wears Prada', 2006, 'David Frankel', 'A young woman from the Midwest gets more than she bargained for when she moves to New York to become a writer and ends up as the assistant to the tyrannical, larger-than-life editor-in-chief of a major fashion magazine.', '/8912AsVuS7Sj915apArUFbv6F9L.jpg', '/gkh6Nt8DtY1XT4gQsyFq9XAVJlJ.jpg'),
('12445', 'Harry Potter and the Deathly Hallows: Part 2', 2011, 'David Yates', 'Harry, Ron and Hermione continue their quest to vanquish the evil Voldemort once and for all. Just as things begin to look hopeless for the young wizards, Harry discovers a trio of magical objects that endow him with powers to rival Voldemort''s formidable skills.', '/c54HpQmuwXjHq2C9wmoACjxoom3.jpg', '/cbcpDn6XJaIGoOil1bKuskU8ds4.jpg'),
('673', 'Harry Potter and the Prisoner of Azkaban', 2004, 'Alfonso Cuarón', 'Harry Potter''s life is in danger once more as dangerous wizard Sirius Black has escaped from Azkaban Prison and is heading to Hogwarts.', '/aWxwnYoe8p2d2fcxOqtvAtJ72Rw.jpg', '/htmYEfH7TQgzsXHCnNXxmoYKQtL.jpg'),
('438631', 'Dune', 2021, 'Denis Villeneuve', 'Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence - a commodity capable of unlocking humanity''s greatest potential - only those who can conquer their fear will survive.', '/v1tRXZ4JtD2Iv6fjkPvT4GiwslV.jpg', '/h3HsfV8Kn9Sz2QWUYYdP5ya23hx.jpg'),
('424', 'Schindler''s List', 1993, 'Steven Spielberg', 'The true story of how businessman Oskar Schindler saved over a thousand Jewish lives from the Nazis while they worked as slaves in his factory during World War II.', '/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg', '/zb6fM1CX41D9rF9hdgclu0peUmy.jpg'),
('12444', 'Harry Potter and the Deathly Hallows: Part 1', 2010, 'David Yates', 'Harry, Ron and Hermione walk away from their last year at Hogwarts to find and destroy the remaining Horcruxes, putting an end to Voldemort''s bid for immortality. But with Harry''s beloved Dumbledore dead and Voldemort''s unscrupulous Death Eaters on the loose, the world is more dangerous than ever.', '/iGoXIpQb7Pot00EEdwpwPajheZ5.jpg', '/vcrgU0KaNj5mKUCIQSUdiQwTE9y.jpg'),
('76341', 'Mad Max: Fury Road', 2015, 'George Miller', 'An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order.', '/ulcAi4dKpAjHwYGS08vNyx9H6I9.jpg', '/uT895WNwm0aIJRtGizcQhrejWUo.jpg'),
('1168190', 'The Wrecking Crew', 2026, 'Ángel Manuel Soto', 'Estranged half-brothers Jonny and James reunite after their father''s mysterious death. As they search for the truth, buried secrets reveal a conspiracy threatening to tear their family apart.', '/gbVwHl4YPSq6BcC92TQpe7qUTh6.jpg', '/cz4vLJrmaV1zJlRYbxqtvLzeLWB.jpg'),
('414906', 'The Batman', 2022, 'Matt Reeves', 'In his second year of fighting crime, Batman uncovers corruption in Gotham City that connects to his own family while facing a serial killer known as the Riddler.', '/74xTEgt7R36Fpooo50r9T25onhq.jpg', '/IYUD7rAIXzBM91TT3Z5fILUS7n.jpg'),
('284052', 'Doctor Strange', 2016, 'Scott Derrickson', 'After his career is destroyed, a brilliant but arrogant surgeon gets a new lease on life when a sorcerer takes him under her wing and trains him to defend the world against evil.', '/uGBVj3bEbCoZbDjjl9wTxcygko1.jpg', '/kkoiH8ZWxJ9WSAjOadGtuHUQxbm.jpg'),
('1233413', 'Sinners', 2025, 'Ryan Coogler', 'Trying to leave their troubled lives behind, twin brothers return to their hometown to start again, only to discover that an even greater evil is waiting to welcome them back.', '/fWPgbnt2LSqkQ6cdQc0SZN9CpLm.jpg', '/nAxGnGHOsfzufThz20zgmRwKur3.jpg'),
('11', 'Star Wars', 1977, 'George Lucas', 'Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.', '/6FfCtAuVAW8XJjZ7eWeLibRLWTw.jpg', '/yUiXA68FfQeA8cRBhd0Ao0jIRZt.jpg'),
('1380291', 'Tom Clancy''s Jack Ryan: Ghost War', 2026, 'Andrew Bernstein', 'Jack Ryan is reluctantly pulled back into espionage when an international covert mission unravels a deadly conspiracy. Racing against time, he joins CIA allies Mike November & James Greer and sharp MI6 officer Emma Marlowe to battle a rogue black-ops unit in a high-stakes, deeply personal fight.', '/8ehYxUh5MWE41AeE9gkHE8DKzvB.jpg', '/dd31qJxOarrHyGZwYsCzOjobQzP.jpg'),
('539972', 'Kraven the Hunter', 2024, 'J.C. Chandor', 'Kraven Kravinoff''s complex relationship with his ruthless gangster father, Nikolai, starts him down a path of vengeance with brutal consequences, motivating him to become not only the greatest hunter in the world, but also one of its most feared.', '/1GvBhRxY6MELDfxFrete6BNhBB5.jpg', '/bGGjyPqtNc8hhGkPo8W8D8t90bW.jpg'),
('138843', 'The Conjuring', 2013, 'James Wan', 'Paranormal investigators Ed and Lorraine Warren work to help a family terrorized by a dark presence in their farmhouse. Forced to confront a powerful entity, the Warrens find themselves caught in the most terrifying case of their lives.', '/wVYREutTvI2tmxr6ujrHT704wGF.jpg', '/ecKQlAEG95k62SMGhvX83oEqANK.jpg'),
('324786', 'Hacksaw Ridge', 2016, 'Mel Gibson', 'WWII American Army Medic Desmond T. Doss, who served during the Battle of Okinawa, refuses to kill people and becomes the first Conscientious Objector in American history to receive the Congressional Medal of Honor.', '/fnOMP6mjmOmZwmlC1n0K7ivrzt1.jpg', '/vDKRMZGFTKP9nQolzeSB1rB1w6p.jpg'),
('13', 'Forrest Gump', 1994, 'Robert Zemeckis', 'A man with a low IQ has accomplished great things in his life and been present during significant historic events—in each case, far exceeding what anyone imagined he could do. But despite all he has achieved, his one true love eludes him.', '/Cw4hIUIAmSYfK9QfaUW5igp9La.jpg', '/66Kn4XWhkuPkJxOJyPEx4U2CUfN.jpg'),
('1218925', 'Chainsaw Man - The Movie: Reze Arc', 2025, 'Tatsuya Yoshihara', 'In a brutal war between devils, hunters, and secret enemies, a mysterious girl named Reze has stepped into Denji''s world, and he faces his deadliest battle yet, fueled by love in a world where survival knows no rules.', '/crBfxNvvsQV3rATX12EuX4W9ECo.jpg', '/gqTz24ZRsCP6AKjARmEivY7m0cK.jpg'),
('950387', 'A Minecraft Movie', 2025, 'Jared Hess', 'Four misfits find themselves struggling with ordinary problems when they are suddenly pulled through a mysterious portal into the Overworld: a bizarre, cubic wonderland that thrives on imagination. To get back home, they''ll have to master this world while embarking on a magical quest with an unexpected, expert crafter, Steve.', '/yFHHfHcUgGAxziP1C3lLt0q2T4s.jpg', '/2Nti3gYAX513wvhp8IiLL6ZDyOm.jpg'),
('385687', 'Fast X', 2023, 'Louis Leterrier', 'Over many missions and against impossible odds, Dom Toretto and his family have outsmarted, out-nerved and outdriven every foe in their path. Now, they confront the most lethal opponent they''ve ever faced: A terrifying threat emerging from the shadows of the past who''s fueled by blood revenge, and who is determined to shatter this family and destroy everything—and everyone—that Dom loves, forever.', '/fiVW06jE7z9YnO4trhaMEdclSiC.jpg', '/4XM8DUTQb3lhLemJC51Jx4a2EuA.jpg'),
('10195', 'Thor', 2011, 'Kenneth Branagh', 'Against his father Odin''s will, The Mighty Thor - a powerful but arrogant warrior god - recklessly reignites an ancient war. Thor is cast down to Earth and forced to live among humans as punishment. Once here, Thor learns what it takes to be a true hero when the most dangerous villain of his world sends the darkest forces of Asgard to invade Earth.', '/prSfAi1xGrhLQNxVSUFh61xQ4Qy.jpg', '/cDJ61O1STtbWNBwefuqVrRe3d7l.jpg'),
('284054', 'Black Panther', 2018, 'Ryan Coogler', 'King T''Challa returns home to the reclusive, technologically advanced African nation of Wakanda to serve as his country''s new leader. However, T''Challa soon finds that he is challenged for the throne by factions within his own country as well as without. Using powers reserved to Wakandan kings, T''Challa assumes the Black Panther mantle to join with ex-girlfriend Nakia, the queen-mother, his princess-kid sister, members of the Dora Milaje (the Wakandan ''special forces'') and an American secret agent, to prevent Wakanda from being dragged into a world war.', '/uxzzxijgPIY7slzFvMotPv8wjKA.jpg', '/b6ZJZHUdMEFECvGiDpJjlfUWela.jpg'),
('129', 'Spirited Away', 2001, 'Hayao Miyazaki', 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.', '/39wmItIWsg5sZMyRUHLkWBcuVCM.jpg', '/dyJvKsNs2KP8qQnAXbRwDjblViy.jpg'),
('246655', 'X-Men: Apocalypse', 2016, 'Bryan Singer', 'After the re-emergence of the world''s first mutant, world-destroyer Apocalypse, the X-Men must unite to defeat his extinction level plan.', '/ikA8UhYdTGpqbatFa93nIf6noSr.jpg', '/sTQNRqLbfCXolrb5CizAW1dj528.jpg'),
('244786', 'Whiplash', 2014, 'Damien Chazelle', 'Under the direction of a ruthless instructor, a talented young drummer begins to pursue perfection at any cost, even his humanity.', '/7fn624j5lj3xTme2SgiLCeuedmO.jpg', '/wbQa0EnWUyRzQ5d1pHLNRlmsCUP.jpg'),
('10138', 'Iron Man 2', 2010, 'Jon Favreau', 'With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James ''Rhodey'' Rhodes at his side, must forge new alliances – and confront powerful enemies.', '/6WBeq4fCfn7AN0o21W9qNcRF2l9.jpg', '/7lmBufEG7P7Y1HClYK3gCxYrkgS.jpg'),
('675', 'Harry Potter and the Order of the Phoenix', 2007, 'David Yates', 'When a new professor''s methods leave Hogwarts unprepared to fight the rising tide of evil, Harry teaches students how to defend against the dark arts.', '/5aOyriWkPec0zUDxmHFP9qMmBaj.jpg', '/pkxPkHOPJjOvzfQOclANEBT8OfK.jpg'),
('390062', 'Jungle', 2017, 'Greg McLean', 'In 1981, an enthusiastic young adventurer follows his dreams into the Bolivian Amazon jungle with two friends and a guide with a mysterious past. Their journey quickly turns into a terrifying ordeal as the darkest elements of human nature and the deadliest threats of the wilderness lead to an all-out fight for survival.', '/tDgxknTVwrScxpCYyGUjXSn5NRk.jpg', '/tav8VVa6H6KooK5rFhAG2jT5ZNx.jpg'),
('807', 'Se7en', 1995, 'David Fincher', 'Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the "seven deadly sins" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Somerset researches each sin in an effort to get inside the killer''s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.', '/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg', '/i5H7zusQGsysGQ8i6P361Vnr0n2.jpg'),
('497', 'The Green Mile', 1999, 'Frank Darabont', 'A supernatural tale set on death row in a Southern prison, where gentle giant John Coffey possesses the mysterious power to heal people''s ailments. When the cell block''s head guard, Paul Edgecomb, recognizes Coffey''s miraculous gift, he tries desperately to help stave off the condemned man''s execution.', '/8VG8fDNiy50H4FedGwdSVUPoaJe.jpg', '/amZavErrjrdgDwhsIdpWxHNenIx.jpg'),
('76338', 'Thor: The Dark World', 2013, 'Alan Taylor', 'Thor fights to restore order across the cosmos… but an ancient race led by the vengeful Malekith returns to plunge the universe back into darkness. Faced with an enemy that even Odin and Asgard cannot withstand, Thor must embark on his most perilous and personal journey yet, one that will reunite him with Jane Foster and force him to sacrifice everything to save us all.', '/wp6OxE4poJ4G7c0U2ZIXasTSMR7.jpg', '/5QEOy0QEpad9QsXeMxuGHPXMale.jpg'),
('18', 'The Fifth Element', 1997, 'Luc Besson', 'In 2257, a taxi driver is unintentionally given the task of saving a young girl who is part of the key that will ensure the survival of humanity.', '/fPtlCO1yQtnoLHOwKtWz7db6RGU.jpg', '/jW21PoKwqs79wk6bfiYezox63mK.jpg'),
('1171145', 'Crime 101', 2026, 'Bart Layton', 'When an elusive thief whose high-stakes heists unfold along the iconic 101 freeway in Los Angeles eyes the score of a lifetime, with hopes of this being his final job, his path collides with a disillusioned insurance broker who is facing her own crossroads. Determined to crack the case, a relentless detective closes in on the operation, raising the stakes even higher.', '/tVvpFIoteRHNnoZMhdnwIVwJpCA.jpg', '/kKF4gEiBDArhONlCcunHVgBp3bA.jpg'),
('1022789', 'Inside Out 2', 2024, 'Kelsey Mann', 'Teenager Riley''s mind headquarters is undergoing a sudden demolition to make room for something entirely unexpected: new Emotions! Joy, Sadness, Anger, Fear and Disgust, who’ve long been running a successful operation by all accounts, aren’t sure how to feel when Anxiety shows up. And it looks like she’s not alone.', '/vpnVM9B6NMmQpWeZvzLvDESb2QY.jpg', '/p5ozvmdgsmbWe0H8Xk7Rc8SCwAB.jpg'),
('489', 'Good Will Hunting', 1997, 'Gus Van Sant', 'Will Hunting is a headstrong, working-class genius who is failing the lessons of life. After one too many run-ins with the law, Will''s last chance is a psychology professor, who might be the only man who can reach him.', '/z2FnLKpFi1HPO7BEJxdkv6hpJSU.jpg', '/xj1Sv1xm4Y0ydBueGuf10Y9qM0O.jpg'),
('8587', 'The Lion King', 1994, 'Roger Allers, Rob Minkoff', 'Young lion prince Simba, eager to one day become king of the Pride Lands, grows up under the watchful eye of his father Mufasa; all the while his villainous uncle Scar conspires to take the throne for himself. Amid betrayal and tragedy, Simba must confront his past and find his rightful place in the Circle of Life.', '/sKCr78MXSLixwmZ8DyJLrpMsd15.jpg', '/q00H8EqULYSK74lgevMkhmGGLHn.jpg'),
('950396', 'The Gorge', 2025, 'Scott Derrickson', 'Two highly trained operatives grow close from a distance after being sent to guard opposite sides of a mysterious gorge. When an evil below emerges, they must work together to survive what lies within.', '/7iMBZzVZtG0oBug4TfqDb9ZxAOa.jpg', '/9nhjGaFLKtddDPtPaX5EmKqsWdH.jpg'),
('1241982', 'Moana 2', 2024, 'David G. Derrick Jr., Jason Hand, Dana Ledoux Miller', 'After receiving an unexpected call from her wayfinding ancestors, Moana journeys alongside Maui and a new crew to the far seas of Oceania and into dangerous, long-lost waters for an adventure unlike anything she''s ever faced.', '/aLVkiINlIeCkcZIzb7XHzPYgO6L.jpg', '/vYqt6kb4lcF8wwqsMMaULkP9OEn.jpg'),
('293660', 'Deadpool', 2016, 'Tim Miller', 'The origin story of former Special Forces operative turned mercenary Wade Wilson, who, after being subjected to a rogue experiment that leaves him with accelerated healing powers, adopts the alter ego Deadpool. Armed with his new abilities and a dark, twisted sense of humor, Deadpool hunts down the man who nearly destroyed his life.', '/3E53WEZJqP6aM84D8CckXx4pIHw.jpg', '/en971MEXui9diirXlogOrPKmsEn.jpg'),
('10193', 'Toy Story 3', 2010, 'Lee Unkrich', 'Woody, Buzz, and the rest of Andy''s toys haven''t been played with in years. With Andy about to go to college, the gang find themselves accidentally left at a nefarious day care center. The toys must band together to escape and return home to Andy.', '/AbbXspMOwdvwWZgVN0nabZq03Ec.jpg', '/uAfhsySkr1UzQg1zdg3dZQRz9Fd.jpg'),
('19995', 'Avatar', 2009, 'James Cameron', 'In the 22nd century, a paraplegic Marine is dispatched to the moon Pandora on a unique mission, but becomes torn between following orders and protecting an alien civilization.', '/gKY6q7SjCkAU6FqvqWybDYgUKIF.jpg', '/vL5LR6WdxWPjLPFRLe133jXWsh5.jpg'),
('106646', 'The Wolf of Wall Street', 2013, 'Martin Scorsese', 'A New York stockbroker refuses to cooperate in a large securities fraud case involving corruption on Wall Street, corporate banking world and mob infiltration. Based on Jordan Belfort''s autobiography.', '/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg', '/7Nwnmyzrtd0FkcRyPqmdzTPppQa.jpg'),
('122917', 'The Hobbit: The Battle of the Five Armies', 2014, 'Peter Jackson', 'Following Smaug''s attack on Laketown, Bilbo and the dwarves try to defend Erebor''s mountain of treasure from others who claim it: the men of the ruined Laketown and the elves of Mirkwood. Meanwhile an army of Orcs led by Azog the Defiler is marching on Erebor, fueled by the rise of the dark lord Sauron. Dwarves, elves and men must unite, and the hope for Middle-Earth falls into Bilbo''s hands.', '/xT98tLqatZPQApyRmlPL12LtiWp.jpg', '/3UbaCMmqOd7mca4Y5DOzY2ZVTyX.jpg'),
('1054867', 'One Battle After Another', 2025, 'Paul Thomas Anderson', 'Washed-up revolutionary Bob exists in a state of stoned paranoia, surviving off-grid with his spirited, self-reliant daughter, Willa. When his evil nemesis resurfaces after 16 years and she goes missing, the former radical scrambles to find her, father and daughter both battling the consequences of his past.', '/lbBWwxBht4JFP5PsuJ5onpMqugW.jpg', '/zpEWFNqoN8Qg1SzMMHmaGyOBTdW.jpg'),
('335984', 'Blade Runner 2049', 2017, 'Denis Villeneuve', 'Thirty years after the events of the first film, a new blade runner, LAPD Officer K, unearths a long-buried secret that has the potential to plunge what''s left of society into chaos. K''s discovery leads him on a quest to find Rick Deckard, a former LAPD blade runner who has been missing for 30 years.', '/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', '/gNdLJU9TxrpGx4dkZidjys3fyy0.jpg'),
('857', 'Saving Private Ryan', 1998, 'Steven Spielberg', 'As U.S. troops storm the beaches of Normandy, three brothers lie dead on the battlefield, with a fourth trapped behind enemy lines. Ranger captain John Miller and seven men are tasked with penetrating German-held territory and bringing the boy home.', '/uqx37cS8cpHg8U35f9U5IBlrCV3.jpg', '/bdD39MpSVhKjxarTxLSfX6baoMP.jpg'),
('240', 'The Godfather Part II', 1974, 'Francis Ford Coppola', 'In the continuing saga of the Corleone crime family, a young Vito Corleone grows up in Sicily and in 1910s New York. In the 1950s, Michael Corleone attempts to expand the family business into Las Vegas, Hollywood and Cuba.', '/sSuQTCZwqKrNBNIsksO9IAUoWP9.jpg', '/kGzFbGhp99zva6oZODW5atUtnqi.jpg'),
('299537', 'Captain Marvel', 2019, 'Ryan Fleck, Anna Boden', 'The story follows Carol Danvers as she becomes one of the universe’s most powerful heroes when Earth is caught in the middle of a galactic war between two alien races. Set in the 1990s, Captain Marvel is an all-new adventure from a previously unseen period in the history of the Marvel Cinematic Universe.', '/AtsgWhDnHTq68L0lLsUrCnM7TjG.jpg', '/qAzYK4YPSWDc7aa4R43LcwRIAyb.jpg'),
('1100988', '28 Years Later', 2025, 'Danny Boyle', 'Twenty-eight years after the Rage virus outbreak, a heavily-defended island survives connected to the mainland by a single causeway. When one of the group leaves the island into the dark heart of the mainland, he discovers secrets, wonders, and horrors that have mutated not only the infected but other survivors as well.', '/n5FygjEppOvac6yEaowi26nTyw3.jpg', '/6WqqEjiycNvDLjbEClM1zCwIbDD.jpg'),
('198663', 'The Maze Runner', 2014, 'Wes Ball', 'A teenager with no memory of his past finds himself among a group of boys living in a walled enclosure surrounded by a massive, ever-changing maze. As he struggles to adapt to their rules and society, he begins to uncover clues that may lead to escape and the truth behind their confinement.', '/ode14q7WtDugFDp78fo9lCsmay9.jpg', '/eTlcNXGv32zkVI7ZDHhfeaKHXKQ.jpg'),
('502356', 'The Super Mario Bros. Movie', 2023, 'Aaron Horvath, Michael Jelenic', 'While working underground to fix a water main, Brooklyn plumbers—and brothers—Mario and Luigi are transported down a mysterious pipe and wander into a magical new world. But when the brothers are separated, Mario embarks on an epic quest to find Luigi.', '/qNBAXBIQlnOThrVvA6mA2B5ggV6.jpg', '/9n2tJBplPbgR2ca05hS5CKXwP2c.jpg'),
('1198994', 'Send Help', 2026, 'Sam Raimi', 'Two colleagues become stranded on a deserted island, the only survivors of a plane crash. On the island, they must overcome past grievances and work together to survive, but ultimately, it''s a battle of wills and wits to make it out alive.', '/zbJWVHOtj3ljBzWgL1P8pxP03Up.jpg', '/bpp58yHuQmpt6xwggI63mVRw7po.jpg'),
('552524', 'Lilo & Stitch', 2025, 'Dean Fleischer Camp', 'The wildly funny and touching story of a lonely Hawaiian girl and the fugitive alien who helps to mend her broken family.', '/ckQzKpQJO4ZQDCN5evdpKcfm7Ys.jpg', '/7Zx3wDG5bBtcfk8lcnCWDOLM4Y4.jpg'),
('767', 'Harry Potter and the Half-Blood Prince', 2009, 'David Yates', 'Dumbledore tries to prepare Harry for the final battle with Voldemort while Death Eaters wreak havoc in both Muggle and Wizard worlds.', '/z7uo9zmQdQwU5ZJHFpv2Upl30i1.jpg', '/ze6Mx4QE5mQVXRYmG2flncqqle4.jpg'),
('1078605', 'Weapons', 2025, 'Zach Cregger', 'When all but one child from the same class mysteriously vanish on the same night at exactly the same time, a community is left questioning who or what is behind their disappearance.', '/cpf7vsRZ0MYRQcnLWteD5jK9ymT.jpg', '/8VyTWJrNEyV2MTWvniDVp0MpOAe.jpg'),
('558', 'Spider-Man 2', 2004, 'Sam Raimi', 'Peter Parker is going through a major identity crisis. Burned out from being Spider-Man, he decides to shelve his superhero alter ego, which leaves the city suffering in the wake of carnage left by the evil Doc Ock. In the meantime, Parker still can''t act on his feelings for Mary Jane Watson, a girl he''s loved since childhood. A certain anger begins to brew in his best friend Harry Osborn as well...', '/aGuvNAaaZuWXYQQ6N2v7DeuP6mB.jpg', '/6al048Lat3eLVQOuKtc9h6Tu94d.jpg'),
('1368314', 'Passenger', 2026, 'André Øvredal', 'After a young couple witnesses a gruesome highway accident, they soon realize they did not leave the crash scene alone, as a demonic presence called the Passenger that won''t stop until it claims them both turns their van life adventure into a nightmare.', '/2sOEJzhPzjTkZSlPbGxOJ7xgIyS.jpg', '/3pDfu71mrzSuFYyIfnKEjt8z4BC.jpg'),
('177572', 'Big Hero 6', 2014, 'Chris Williams, Don Hall', 'A special bond develops between plus-sized inflatable robot Baymax, and prodigy Hiro Hamada, who team up with a group of friends to form a band of high-tech heroes.', '/2mxS4wUimwlLmI1xp6QW6NSU361.jpg', '/4s2d3xdyqotiVNHTlTlJjrr3q0H.jpg'),
('808', 'Shrek', 2001, 'Andrew Adamson, Vicky Jenson', 'It ain''t easy bein'' green -- especially if you''re a likable (albeit smelly) ogre named Shrek. On a mission to retrieve a gorgeous princess from the clutches of a fire-breathing dragon, Shrek teams up with an unlikely compatriot -- a wisecracking donkey.', '/iB64vpL3dIObOtMZgX3RqdVdQDc.jpg', '/sRvXNDItGlWCqtO3j6wks52FmbD.jpg'),
('549509', 'The Brutalist', 2024, 'Brady Corbet', 'When an innovative modern architect flees post-war Europe, he is given the opportunity to rebuild his legacy. Set during the dawn of the modern United States (in Pennsylvania), his wife joins him, and their lives are forever changed by a demanding, wealthy patron.', '/vP7Yd6couiAaw9jgMd5cjMRj3hQ.jpg', '/hmZnqijPaaACjenDkrbWcCmcADI.jpg'),
('283995', 'Guardians of the Galaxy Vol. 2', 2017, 'James Gunn', 'The Guardians must fight to keep their newfound family together as they unravel the mysteries of Peter Quill''s true parentage.', '/y4MBh0EjBlMuOzv9axM4qJlmhzz.jpg', '/bW93ycPSSi3Hxx1NvlMX5qm2mQu.jpg'),
('22', 'Pirates of the Caribbean: The Curse of the Black Pearl', 2003, 'Gore Verbinski', 'When wily pirate Captain Barbossa seizes Jack Sparrow’s beloved ship, the Black Pearl, and kidnaps the governor’s daughter, Elizabeth Swann, blacksmith Will Turner reluctantly teams up with the unpredictable pirate Jack to rescue her—only to uncover a terrifying curse that turns Barbossa’s crew into the undead.', '/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg', '/uRNgkJSkNBFbbn9fPsEjDIy8Sh3.jpg'),
('11036', 'The Notebook', 2004, 'Nick Cassavetes', 'An epic love story centered around an older man who reads aloud to a woman with Alzheimer''s. From a faded notebook, the old man''s words bring to life the story about a couple who is separated by World War II, and is then passionately reunited, seven years later, after they have taken different paths.', '/rNzQyW4f8B8cQeg7Dgj3n6eT5k9.jpg', '/zdXnJqBaGFVtLoPNuMeKfEYUViZ.jpg'),
('218', 'The Terminator', 1984, 'James Cameron', 'In the post-apocalyptic future, reigning tyrannical supercomputers teleport a cyborg assassin known as the "Terminator" back to 1984 to kill Sarah Connor, whose unborn son is destined to lead insurgents against 21st century mechanical hegemony. Meanwhile, the human-resistance movement dispatches a lone warrior to safeguard Sarah. Can he stop the virtually indestructible killing machine?', '/qvktm0BHcnmDpul4Hz01GIazWPr.jpg', '/ffdqHMWkh1h9MABwIfbfRJhgFW6.jpg'),
('564', 'The Mummy', 1999, 'Stephen Sommers', 'Dashing legionnaire Rick O''Connell stumbles upon the hidden ruins of Hamunaptra while in the midst of a battle to claim the area in 1920s Egypt. It has been over three thousand years since former High Priest Imhotep suffered a fate worse than death as a punishment for a forbidden love—along with a curse that guarantees eternal doom upon the world if he is ever awoken.', '/yhIsVvcUm7QxzLfT6HW2wLf5ajY.jpg', '/8zLS8p1tRyWFLRFfmgQq0j5WE6z.jpg'),
('497698', 'Black Widow', 2021, 'Cate Shortland', 'Natasha Romanoff, also known as Black Widow, confronts the darker parts of her ledger when a dangerous conspiracy with ties to her past arises. Pursued by a force that will stop at nothing to bring her down, Natasha must deal with her history as a spy and the broken relationships left in her wake long before she became an Avenger.', '/qAZ0pzat24kLdO3o8ejmbLxyOac.jpg', '/keIxh0wPr2Ymj0Btjh4gW7JJ89e.jpg'),
('20352', 'Despicable Me', 2010, 'Pierre Coffin, Chris Renaud', 'Determined to prove he''s the world''s greatest supervillain, Gru hatches an audacious plan to steal the Moon. To pull it off, he adopts three orphaned girls—Margo, Edith, and Agnes—intending to use them as pawns in his scheme. But the unexpected bond they form forces him to question the criminal life he''s always known.', '/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg', '/2XSeKDmIa2KxaiJy4J9e8FrIZhk.jpg'),
('585', 'Monsters, Inc.', 2001, 'Pete Docter', 'Lovable Sulley and his wisecracking sidekick Mike Wazowski are the top scare team at Monsters, Inc., the scream-processing factory in Monstropolis. When a little girl named Boo wanders into their world, it''s the monsters who are scared silly, and it''s up to Sulley and Mike to keep her out of sight and get her back home.', '/wFSpyMsp7H0ttERbxY7Trlv8xry.jpg', '/sDTnMOJ3H5wI38OxObmCtK7wfd5.jpg'),
('615656', 'Meg 2: The Trench', 2023, 'Ben Wheatley', 'An exploratory dive into the deepest depths of the ocean of a daring research team spirals into chaos when a malevolent mining operation threatens their mission and forces them into a high-stakes battle for survival.', '/4m1Au3YkjqsxF8iwQy0fPYSxE0h.jpg', '/5mzr6JZbrqnqD8rCEvPhuCE5Fw2.jpg'),
('912649', 'Venom: The Last Dance', 2024, 'Kelly Marcel', 'Eddie and Venom are on the run. Hunted by both of their worlds and with the net closing in, the duo are forced into a devastating decision that will bring the curtains down on Venom and Eddie''s last dance.', '/vGXptEdgZIhPg3cGlc7e8sNPC2e.jpg', '/3V4kLQg0kSqPLctI5ziYWabAZYF.jpg'),
('713704', 'Evil Dead Rise', 2023, 'Lee Cronin', 'A reunion between two estranged sisters gets cut short by the rise of flesh-possessing demons, thrusting them into a primal battle for survival as they face the most nightmarish version of family imaginable.', '/5ik4ATKmNtmJU6AYD0bLm56BCVM.jpg', '/7bWxAsNPv9CXHOhZbJVlj2KxgfP.jpg'),
('11324', 'Shutter Island', 2010, 'Martin Scorsese', 'World War II soldier-turned-U.S. Marshal Teddy Daniels investigates the disappearance of a patient from a hospital for the criminally insane, but his efforts are compromised by troubling visions and a mysterious doctor.', '/nrmXQ0zcZUL8jFLrakWc90IR8z9.jpg', '/rbZvGN1A1QyZuoKzhCw8QPmf2q0.jpg'),
('575265', 'Mission: Impossible - The Final Reckoning', 2025, 'Christopher McQuarrie', 'Ethan Hunt and team continue their search for the terrifying AI known as the Entity — which has infiltrated intelligence networks all over the globe — with the world''s governments and a mysterious ghost from Hunt''s past on their trail. Joined by new allies and armed with the means to shut the Entity down for good, Hunt is in a race against time to prevent the world as we know it from changing forever.', '/iKPsC9EFUafRP9SrUznI61getVP.jpg', '/538U9snNc2fpnOmYXAPUh3zn31H.jpg'),
('68721', 'Iron Man 3', 2013, 'Shane Black', 'When Tony Stark''s world is torn apart by a formidable terrorist called the Mandarin, he starts an odyssey of rebuilding and retribution.', '/qhPtAc1TKbMPqNvcdXSOn9Bn7hZ.jpg', '/iVped1djsF0tvGkvnHbzsE3ZPTF.jpg'),
('939243', 'Sonic the Hedgehog 3', 2024, 'Jeff Fowler', 'Sonic, Knuckles, and Tails reunite against a powerful new adversary, Shadow, a mysterious villain with powers unlike anything they have faced before. With their abilities outmatched in every way, Team Sonic must seek out an unlikely alliance in hopes of stopping Shadow and protecting the planet.', '/d8Ryb8AunYAuycVKDp5HpdWPKgC.jpg', '/zOpe0eHsq0A2NvNyBbtT6sj53qV.jpg'),
('574475', 'Final Destination Bloodlines', 2025, 'Adam Stein, Zach Lipovsky', 'Plagued by a violent recurring nightmare, college student Stefanie heads home to track down the one person who might be able to break the cycle and save her family from the grisly demise that inevitably awaits them all.', '/6WxhEvFsauuACfv8HyoVX6mZKFj.jpg', '/uIpJPDNFoeX0TVml9smPrs9KUVx.jpg'),
('10681', 'WALL·E', 2008, 'Andrew Stanton', 'After hundreds of years doing what he was built for, WALL•E— a robot designed to clean up the earth—discovers a new purpose in life when he meets a sleek search robot named EVE. EVE comes to realize that WALL•E has inadvertently stumbled upon the key to the planet''s future, and races back to space to report to the humans. Meanwhile, WALL•E chases EVE across the galaxy and sets into motion one of the most imaginative adventures ever brought to the big screen.', '/hbhFnRzzg6ZDmm8YAmxBnQpQIPh.jpg', '/nYs4ZwnJBK4AgljhvzwNz7fpr3E.jpg'),
('1266127', 'Ready or Not: Here I Come', 2026, 'Matt Bettinelli-Olpin, Tyler Gillett', 'Moments after surviving an all-out attack from the Le Domas family, Grace discovers she’s reached the next level of the nightmarish game — and this time with her estranged sister Faith at her side. Grace has one chance to survive, keep her sister alive, and claim the High Seat of the Council that controls the world. Four rival families are hunting her for the throne, and whoever wins rules it all.', '/13ZcJzSGEqVgDSqsS9U5EkQwPkV.jpg', '/fx2cEuadZK28VHKkc0F1nFR96i0.jpg'),
('558449', 'Gladiator II', 2024, 'Ridley Scott', 'Years after witnessing the death of the revered hero Maximus at the hands of his uncle, Lucius is forced to enter the Colosseum after his home is conquered by the tyrannical Emperors who now lead Rome with an iron fist. With rage in his heart and the future of the Empire at stake, Lucius must look to his past to find strength and honor to return the glory of Rome to its people.', '/2cxhvwyEwRlysAmRH4iodkvo0z5.jpg', '/tOqIwliWMovSIZ9DyvHcHI7p2im.jpg'),
('1317288', 'Marty Supreme', 2025, 'Josh Safdie', 'Marty Mauser, a young man with a dream no one respects, goes to hell and back in pursuit of greatness.', '/lYWEXbQgRTR4ZQleSXAgRbxAjvq.jpg', '/6h7w8R4BA7vubEmEEW5vYEjuoz6.jpg'),
('49026', 'The Dark Knight Rises', 2012, 'Christopher Nolan', 'Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.', '/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg', '/y2DB71C4nyIdMrANijz8mzvQtk6.jpg'),
('18785', 'The Hangover', 2009, 'Todd Phillips', 'When three friends finally come to after a raucous night of bachelor-party revelry, they find a baby in the closet and a tiger in the bathroom. But they can''t seem to locate their best friend, Doug – who''s supposed to be tying the knot. Launching a frantic search for Doug, the trio perseveres through a nasty hangover to try to make it to the church on time.', '/A0uS9rHR56FeBtpjVki16M5xxSW.jpg', '/iuRVt8tFiXDPGgzavhuSa3QHRxD.jpg'),
('1156594', 'Our Fault', 2025, 'Domingo González', 'Jenna and Lion''s wedding brings about the long-awaited reunion between Noah and Nick after their breakup. Nick''s inability to forgive Noah stands as an insurmountable barrier. He, heir to his grandfather''s businesses, and she, starting her professional life, resist fueling a flame that''s still alive. But now that their paths have crossed again, will love be stronger than resentment?', '/yzqHt4m1SeY9FbPrfZ0C2Hi9x1s.jpg', '/7QirCB1o80NEFpQGlQRZerZbQEp.jpg'),
('1159559', 'Scream 7', 2026, 'Kevin Williamson', 'When a new Ghostface killer emerges in the quiet town where Sidney Prescott has built a new life, her darkest fears are realized as her daughter becomes the next target. Determined to protect her family, Sidney must face the horrors of her past to put an end to the bloodshed once and for all.', '/jjyuk0edLiW8vOSnlfwWCCLpbh5.jpg', '/3eUyLEF5M0ky3h6KJsWiWzaakB8.jpg'),
('475557', 'Joker', 2019, 'Todd Phillips', 'During the 1980s, a failed stand-up comedian is driven insane and turns to a life of crime and chaos in Gotham City while becoming an infamous psychopathic crime figure.', '/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg', '/rlay2M5QYvi6igbGcFjq8jxeusY.jpg'),
('2062', 'Ratatouille', 2007, 'Brad Bird', 'Remy, a rat, possesses a palate far more refined than that of his fellow comrades. He aspires to become a chef, one who creates rather than scavenges. When fate leads him beneath one of Paris''s finest restaurants, he forms an unusual alliance with a young kitchen worker to pursue his culinary ambitions. As his double life unfolds, Remy must navigate the suspicions of the calculating Head Chef Skinner, the disapproval of Remy’s own colony, and the foreboding presence of renowned food critic Anton Ego, whose judgment can make or break a chef''s legacy.', '/t3vaWRPSf6WjDSamIkKDs1iQWna.jpg', '/jQ6Vuxe1CEPMXTF7d0fZgdIBY8U.jpg'),
('863', 'Toy Story 2', 1999, 'John Lasseter', 'Andy heads off to Cowboy Camp, leaving his toys to their own devices. Things shift into high gear when an obsessive toy collector named Al McWhiggen, owner of Al''s Toy Barn kidnaps Woody. Andy''s toys mount a daring rescue mission, Buzz Lightyear meets his match and Woody has to decide where he and his heart truly belong.', '/4rbcp3ng8n1MKHjpeqW0L7Fnpzz.jpg', '/7iUDfakacY1HpajP1DtHrCuDB95.jpg'),
('1430077', 'Hokum', 2026, 'Damian McCarthy', 'When novelist Ohm Bauman retreats to a remote inn to scatter his parents'' ashes, he is consumed by tales of a witch haunting the honeymoon suite. Disturbing visions and a shocking disappearance forces him to confront dark corners of his past.', '/x6rHcQFiYcczLQPrmxXPAicm54E.jpg', '/qY7zVZ7liULhfRoXg4c9Xl83LcR.jpg'),
('604079', 'The Long Walk', 2025, 'Francis Lawrence', 'In a dystopian 1970s America, fifty teenage boys take part in a deadly annual walking contest, forced to maintain a minimum pace or be executed, until only one survivor remains.', '/wobVTa99eW0ht6c1rNNzLkazPtR.jpg', '/2dlt9I2ga6hweywz9zsFUz1PVii.jpg'),
('16869', 'Inglourious Basterds', 2009, 'Quentin Tarantino', 'In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as "The Basterds" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers.', '/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg', '/hwNtEmmugU5Yd7hpfprNWI0DGIn.jpg'),
('39254', 'Real Steel', 2011, 'Shawn Levy', 'Charlie Kenton is a washed-up fighter who retired from the ring when robots took over the sport. After his robot is trashed, he reluctantly teams up with his estranged son to rebuild and train an unlikely contender.', '/4GIeI5K5YdDUkR3mNQBoScpSFEf.jpg', '/pjlxrd646cBYznHoPBWTzz6FujX.jpg'),
('436270', 'Black Adam', 2022, 'Jaume Collet-Serra', 'Nearly 5,000 years after he was bestowed with the almighty powers of the Egyptian gods—and imprisoned just as quickly—Black Adam is freed from his earthly tomb, ready to unleash his unique form of justice on the modern world.', '/rCtreCr4xiYEWDQTebybolIh6Xe.jpg', '/bQXAqRx2Fgc46uCVWgoPz5L5Dtr.jpg'),
('76600', 'Avatar: The Way of Water', 2022, 'James Cameron', 'Set more than a decade after the events of the first film, learn the story of the Sully family (Jake, Neytiri, and their kids), the trouble that follows them, the lengths they go to keep each other safe, the battles they fight to stay alive, and the tragedies they endure.', '/t6HIqrRAclMCA60NsSmeqe9RmNV.jpg', '/kJsPVzdyBrYHLomuNv5SJDXUQ2f.jpg'),
('616037', 'Thor: Love and Thunder', 2022, 'Taika Waititi', 'After his retirement is interrupted by Gorr the God Butcher, a galactic killer who seeks the extinction of the gods, Thor Odinson enlists the help of King Valkyrie, Korg, and ex-girlfriend Jane Foster, who now wields Mjolnir as the Mighty Thor. Together they embark upon a harrowing cosmic adventure to uncover the mystery of the God Butcher’s vengeance and stop him before it’s too late.', '/pIkRyD18kl4FhoCNQuWxWu5cBLM.jpg', '/jsoz1HlxczSuTx0mDl2h0lxy36l.jpg');
INSERT INTO movies (id, title, year, director, overview, poster_path, backdrop_path) VALUES
('38757', 'Tangled', 2010, 'Byron Howard, Nathan Greno', 'Feisty teenager Rapunzel, who has long and magical hair, wants to go and see sky lanterns on her eighteenth birthday, but she''s bound to a tower by her overprotective mother. She strikes a deal with Flynn Rider, a charming wanted thief, and the duo set off on an action-packed escapade.', '/ym7Kst6a4uodryxqbGOxmewF235.jpg', '/cWczNud8Y8i8ab0Z4bxos4myWYO.jpg'),
('150540', 'Inside Out', 2015, 'Pete Docter', 'When 11-year-old Riley moves to a new city, her Emotions team up to help her through the transition. Joy, Fear, Anger, Disgust and Sadness work together, but when Joy and Sadness get lost, they must journey through unfamiliar places to get back home.', '/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg', '/o3i6AfTcWAuNvzAUV3q5lOmi6Gx.jpg'),
('280', 'Terminator 2: Judgment Day', 1991, 'James Cameron', 'Ten years after the events of the original, a reprogrammed T-800 is sent back in time to protect young John Connor from the shape-shifting T-1000. Together with his mother Sarah, he fights to stop Skynet from triggering a nuclear apocalypse.', '/jFTVD4XoWQTcg7wdyJKa8PEds5q.jpg', '/izkMjmhauFx9DjoBQqM5sM5WAwE.jpg'),
('372058', 'Your Name.', 2016, 'Makoto Shinkai', 'High schoolers Mitsuha and Taki are complete strangers living separate lives. But one night, they suddenly switch places. Mitsuha wakes up in Taki’s body, and he in hers. This bizarre occurrence continues to happen randomly, and the two must adjust their lives around each other.', '/vfJFJPepRKapMd5G2ro7klIRysq.jpg', '/8x9iKH8kWA0zdkgNdpAew7OstYe.jpg'),
('945961', 'Alien: Romulus', 2024, 'Fede Álvarez', 'While scavenging the deep ends of a derelict space station, a group of young space colonizers come face to face with the most terrifying life form in the universe.', '/2uSWRTtCG336nuBiG8jOTEUKSy8.jpg', '/iYqSQaWDttQIQzsxg9xHyg0bttG.jpg'),
('1422', 'The Departed', 2006, 'Martin Scorsese', 'To take down South Boston''s Irish Mafia, the police send in one of their own to infiltrate the underworld, not realizing the syndicate has done likewise. While an undercover cop curries favor with the mob kingpin, a career criminal rises through the police ranks. But both sides soon discover there''s a mole among them.', '/nT97ifVT2J1yMQmeq20Qblg61T.jpg', '/6WRrGYalXXveItfpnipYdayFkQB.jpg'),
('567609', 'Ready or Not', 2019, 'Tyler Gillett, Matt Bettinelli-Olpin', 'A young bride''s wedding night turns into her worst nightmare when her ridiculously rich in-laws force her to play a gruesome game of hide-and-seek.', '/oJD9KQFoObZmxAS1je56SIFVNJt.jpg', '/oJ1MIABA0WF0a7MDVQnnMvBdex8.jpg'),
('37165', 'The Truman Show', 1998, 'Peter Weir', 'In a picture-perfect seaside town, an insurance salesman begins to realize that his entire existence may be staged and observed by a vast unseen audience as part of a long-running real-time reality TV show.', '/vuza0WqY239yBXOadKlGwJsZJFE.jpg', '/rmiG2uwcNoGFmBKMoa1pIcf514L.jpg'),
('744275', 'After We Fell', 2021, 'Castille Landon', 'Just as Tessa''s life begins to become unglued, nothing is what she thought it would be. Not her friends nor her family. The only person that she should be able to rely on is Hardin, who is furious when he discovers the massive secret that she''s been keeping. Before Tessa makes the biggest decision of her life, everything changes because of revelations about her family.', '/dU4HfnTEJDf9KvxGS9hgO7BVeju.jpg', '/mxdiaM2tsx8M6W3zLgiPwAkhQfq.jpg'),
('505642', 'Black Panther: Wakanda Forever', 2022, 'Ryan Coogler', 'Queen Ramonda, Shuri, M’Baku, Okoye and the Dora Milaje fight to protect their nation from intervening world powers in the wake of King T’Challa’s death.  As the Wakandans strive to embrace their next chapter, the heroes must band together with the help of War Dog Nakia and Everett Ross and forge a new path for the kingdom of Wakanda.', '/sv1xJUazXeYqALzczSZ3O6nkH75.jpg', '/83H0C66AcvkwpG2738VCTHMY9uv.jpg'),
('260514', 'Cars 3', 2017, 'Brian Fee', 'Blindsided by a new generation of blazing-fast racers, the legendary Lightning McQueen is suddenly pushed out of the sport he loves. To get back in the game, he will need the help of an eager young race technician with her own plan to win, inspiration from the late Fabulous Hudson Hornet, and a few unexpected turns.', '/zg5RDxvIIAKsucjuU2EZJIHEIvz.jpg', '/4mlS1MitcOqdPLhxEFyk9Qwf5rr.jpg'),
('1197306', 'A Working Man', 2025, 'David Ayer', 'Levon Cade left behind a decorated military career in the black ops to live a simple life working construction. But when his boss''s daughter, who is like family to him, is taken by human traffickers, his search to bring her home uncovers a world of corruption far greater than he ever could have imagined.', '/6FRFIogh3zFnVWn7Z6zcYnIbRcX.jpg', '/fTrQsdMS2MUw00RnzH0r3JWHhts.jpg'),
('389', '12 Angry Men', 1957, 'Sidney Lumet', 'The defense and the prosecution have rested and the jury is filing into the jury room to decide if a young Spanish-American is guilty or innocent of murdering his father. What begins as an open and shut case soon becomes a mini-drama of each of the jurors'' prejudices and preconceptions about the trial, the accused, and each other.', '/ppd84D2i9W8jXmsyInGyihiSyqz.jpg', '/qqHQsStV6exghCM7zbObuYBiYxw.jpg'),
('12', 'Finding Nemo', 2003, 'Andrew Stanton', 'Nemo, an adventurous young clownfish, is unexpectedly taken from his Great Barrier Reef home to a dentist''s office aquarium. It''s up to his worrisome father Marlin and a friendly but forgetful fish Dory to bring Nemo home -- meeting vegetarian sharks, surfer dude turtles, hypnotic jellyfish, hungry seagulls, and more along the way.', '/eHuGQ10FUzK1mdOY69wF5pGgEf5.jpg', '/eCynaAOgYYiw5yN5lBwz3IxqvaW.jpg'),
('228150', 'Fury', 2014, 'David Ayer', 'April, 1945. As the Allies make their final push in the European Theater, a battle-hardened army sergeant commands a Sherman tank with a five-man crew on a deadly mission behind enemy lines.', '/pfte7wdMobMF4CVHuOxyu6oqeeA.jpg', '/95ckrV6wQgbffurAVmETQ5YKASL.jpg'),
('109445', 'Frozen', 2013, 'Jennifer Lee, Chris Buck', 'Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She''s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.', '/itAKcobTYGpYT8Phwjd8c9hleTo.jpg', '/rj58WQ9ImI0mYDptXdM7euX1Wjt.jpg'),
('259693', 'The Conjuring 2', 2016, 'James Wan', 'Lorraine and Ed Warren travel to north London to help a single mother raising four children alone in a house plagued by malicious spirits.', '/zEqyD0SBt6HL7W9JQoWwtd5Do1T.jpg', '/hD9zZYKYb1xBgcm8XIfyvclSkjs.jpg'),
('207', 'Dead Poets Society', 1989, 'Peter Weir', 'At an elite, old-fashioned boarding school in New England, a passionate English teacher inspires his students to rebel against convention and seize the potential of every day, courting the disdain of the stern headmaster.', '/tNvKkSnnn4Z6RCBThyK1gfCSSvv.jpg', '/lFIXZpwwlF9hg8NM3RazaIJDuaj.jpg'),
('578', 'Jaws', 1975, 'Steven Spielberg', 'When the seaside community of Amity finds itself under attack by a dangerous great white shark, the town''s chief of police, a young marine biologist, and a grizzled shark hunter embark on a desperate quest to kill the beast before it strikes again.', '/lxM6kqilAdpdhqUl2biYp5frUxE.jpg', '/i1yf91svRHX45l9BXL8rVFzLoPH.jpg'),
('4935', 'Howl''s Moving Castle', 2004, 'Hayao Miyazaki', 'Sophie, a young milliner, is turned into an elderly woman by a witch who enters her shop and curses her. She encounters a wizard named Howl and gets caught up in his resistance to fighting for the king.', '/13kOl2v0nD2OLbVSHnHk8GUFEhO.jpg', '/nv5wwZou159v5OC61i4ElR7OqyY.jpg'),
('1306368', 'The Rip', 2026, 'Joe Carnahan', 'Trust frays when a team of Miami cops discovers millions in cash inside a run-down stash house, calling everyone — and everything — into question.', '/4wsYWH73Hb1B6noGIFaRQSAkuXj.jpg', '/kwNIQW7egAmI66sb0zIugMbpCfU.jpg'),
('614945', 'Voicemails for Isabelle', 2026, 'Leah McKendrick', 'A young woman''s hilariously confessional voicemails to her late sister are unknowingly redirected to a stranger, who begins to fall in love from afar.', '/canZTWSxACSnAluir3dCtMxKpA1.jpg', '/2WU6Y6aonzD6uAaCmNnEFlesxxJ.jpg'),
('402431', 'Wicked', 2024, 'Jon M. Chu', 'In the land of Oz, ostracized and misunderstood green-skinned Elphaba is forced to share a room with the popular aristocrat Glinda at Shiz University, and the two''s unlikely friendship is tested as they begin to fulfill their respective destinies as Glinda the Good and the Wicked Witch of the West.', '/xDGbZ0JJ3mYaGKy4Nzd9Kph6M9L.jpg', '/fyZ6SDUS4o9jp2EHxfZa3qS9ean.jpg'),
('301528', 'Toy Story 4', 2019, 'Josh Cooley', 'Woody has always been confident about his place in the world, devoted to taking care of his kid—whether that''s Andy or Bonnie. But after Bonnie creates a reluctant new toy called "Forky", a road trip adventure alongside old and new friends challenges everything Woody believes about loyalty, purpose, and what it truly means to be a toy.', '/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg', '/q62bpQ67qaXY0u6b2wFEnQYIbPd.jpg'),
('769', 'GoodFellas', 1990, 'Martin Scorsese', 'The true story of Henry Hill, a half-Irish, half-Sicilian Brooklyn kid who is adopted by neighbourhood gangsters at an early age and climbs the ranks of a Mafia family under the guidance of Jimmy Conway.', '/9OkCLM73MIU2CrKZbqiT8Ln1wY2.jpg', '/gILte6Zd7m1YneIr6MVhh30S9pr.jpg'),
('1087192', 'How to Train Your Dragon', 2025, 'Dean DeBlois', 'On the rugged isle of Berk, where Vikings and dragons have been bitter enemies for generations, Hiccup stands apart, defying centuries of tradition when he befriends Toothless, a feared Night Fury dragon. Their unlikely bond reveals the true nature of dragons, challenging the very foundations of Viking society.', '/53dsJ3oEnBhTBVMigWJ9tkA5bzJ.jpg', '/AeDzjt00Hfh9CuW7TIUdYBJmWYM.jpg'),
('156022', 'The Equalizer', 2014, 'Antoine Fuqua', 'McCall believes he has put his mysterious past behind him and dedicated himself to beginning a new, quiet life. But when he meets Teri, a young girl under the control of ultra-violent Russian gangsters, he can’t stand idly by – he has to help her. Armed with hidden skills that allow him to serve vengeance against anyone who would brutalize the helpless, McCall comes out of his self-imposed retirement and finds his desire for justice reawakened. If someone has a problem, if the odds are stacked against them, if they have nowhere else to turn, McCall will help. He is The Equalizer.', '/9u4yW7yPA0BQ2pv9XwiNzItwvp8.jpg', '/9vAoubhoZE8aSkUZoSfxs3UWZhO.jpg'),
('297802', 'Aquaman', 2018, 'James Wan', 'Half-human, half-Atlantean Arthur Curry is taken on the journey of his lifetime to discover if he is worth of being a king.', '/ufl63EFcc5XpByEV2Ecdw6WJZAI.jpg', '/9QusGjxcYvfPD1THg6oW3RLeNn7.jpg'),
('447273', 'Snow White', 2025, 'Marc Webb', 'Following the benevolent King''s disappearance, the Evil Queen dominated the once fair land with a cruel streak. Princess Snow White flees the castle when the Queen, in her jealousy over Snow White''s inner beauty, tries to kill her. Deep into the dark woods, she stumbles upon seven magical dwarves and a young bandit named Jonathan. Together, they strive to survive the Queen''s relentless pursuit and aspire to take back the kingdom.', '/oLxWocqheC8XbXbxqJ3x422j9PW.jpg', '/tyfO9jHgkhypUFizRVYD0bytPjP.jpg'),
('286217', 'The Martian', 2015, 'Ridley Scott', 'During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive.', '/fASz8A0yFE3QB6LgGoOfwvFSseV.jpg', '/lzMS0CI3FLQYC5EgJoWeIaEt0lm.jpg'),
('1062722', 'Frankenstein', 2025, 'Guillermo del Toro', 'Dr. Victor Frankenstein, a brilliant but egotistical scientist, brings a creature to life in a monstrous experiment that ultimately leads to the undoing of both the creator and his tragic creation.', '/g4JtvGlQO7DByTI6frUobqvSL3R.jpg', '/hpXBJxLD2SEf8l2CspmSeiHrBKX.jpg'),
('14160', 'Up', 2009, 'Pete Docter', 'Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.', '/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg', '/hGGC9gKo7CFE3fW07RA587e5kol.jpg'),
('348', 'Alien', 1979, 'Ridley Scott', 'During its return to the earth, commercial spaceship Nostromo intercepts a distress signal from a distant planet. When a three-member team of the crew discovers a chamber containing thousands of eggs on the planet, a creature inside one of the eggs attacks an explorer. The entire crew is unaware of the impending nightmare set to descend upon them when the alien parasite planted inside its unfortunate host is birthed.', '/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg', '/AmR3JG1VQVxU8TfAvljUhfSFUOx.jpg'),
('330457', 'Frozen II', 2019, 'Jennifer Lee, Chris Buck', 'Elsa, Anna, Kristoff and Olaf head far into the forest to learn the truth about an ancient mystery of their kingdom.', '/mINJaa34MtknCYl5AjtNJzWj8cD.jpg', '/AoSZyb37ljMAxw0RdeQEBHKtgcc.jpg'),
('1038392', 'The Conjuring: Last Rites', 2025, 'Michael Chaves', 'Paranormal investigators Ed and Lorraine Warren take on one last terrifying case involving mysterious entities they must confront.', '/byWgphT74ClOVa8EOGzYDkl8DVL.jpg', '/i8MupUe4xgmYXoRNAQMYvuoexSU.jpg'),
('102899', 'Ant-Man', 2015, 'Peyton Reed', 'Armed with the astonishing ability to shrink in scale but increase in strength, master thief Scott Lang must embrace his inner-hero and help his mentor, Doctor Hank Pym, protect the secret behind his spectacular Ant-Man suit from a new generation of towering threats. Against seemingly insurmountable obstacles, Pym and Lang must plan and pull off a heist that will save the world.', '/rQRnQfUl3kfp78nCWq8Ks04vnq1.jpg', '/1K3JmSNUN8OpjYsCjc0Hy0SYxAb.jpg'),
('1202033', 'Enola Holmes 3', 2026, 'Philip Barantini', 'Adventure follows detective Enola Holmes to Malta, where her plans to tie the knot unravel when Sherlock''s disappearance plunges her into a perilous case.', '/7kRYHH9H9PjBFwz1FprbHB2AAjI.jpg', '/jLuGZc84MvPYCQomQg9DI72mstt.jpg'),
('1124', 'The Prestige', 2006, 'Christopher Nolan', 'A mysterious story of two magicians whose intense rivalry leads them on a life-long battle for supremacy -- full of obsession, deceit and jealousy with dangerous and deadly consequences.', '/Ag2B2KHKQPukjH7WutmgnnSNurZ.jpg', '/z3br1ub7spqGMkxgjgJSdM4DC21.jpg'),
('1632181', 'Accidental Partners', 2026, 'Ihtzi Hurtado', 'Two women discover they were both scammed by the same man (who also got them pregnant). They form an alliance to take revenge.', '/j0CIVzeR7hRAPBPGR54qDZoOQpp.jpg', '/iCML6fBe3X0y06P33bM7dyYXPKZ.jpg'),
('77', 'Memento', 2000, 'Christopher Nolan', 'Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife''s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he''s going, or why.', '/nzlv62aC0octS5AklAiWpXLX9Z0.jpg', '/7Wev9JMo6R5XAfz2KDvXb7oPMmy.jpg'),
('12207', 'The Legend of Drunken Master', 1994, 'Lau Kar-leung', 'Returning home with his father after a shopping expedition, Wong Fei-Hong is unwittingly caught up in the battle between foreigners who wish to export ancient Chinese artifacts and loyalists who don''t want the pieces to leave the country. Fei-Hong must fight against the foreigners using his Drunken Boxing style, and overcome his father''s antagonism as well.', '/xqUBrSBtPYLvCtfqHF5sapU6Div.jpg', '/zo14UuFDTVy91cBNWHplHCqHCPt.jpg'),
('62', '2001: A Space Odyssey', 1968, 'Stanley Kubrick', 'Humanity finds a mysterious object buried beneath the lunar surface and sets off to find its origins with the help of HAL 9000, the world''s most advanced super computer.', '/ve72VxNqjGM69Uky4WTo2bK6rfq.jpg', '/w5IDXtifKntw0ajv2co7jFlTQDM.jpg'),
('38365', 'Grown Ups', 2010, 'Dennis Dugan', 'After their high school basketball coach passes away, five good friends and former teammates reunite for a Fourth of July holiday weekend.', '/cQGM5k1NtU85n4TUlrOrwijSCcm.jpg', '/kARonxQpuSZdFraTKlCThWOBCtu.jpg'),
('1175942', 'The Bad Guys 2', 2025, 'Pierre Perifel', 'The now-reformed Bad Guys are trying (very, very hard) to be good, but instead find themselves hijacked into a high-stakes, globe-trotting heist, masterminded by a new team of criminals they never saw coming: The Bad Girls.', '/26oSPnq0ct59l07QOXZKyzsiRtN.jpg', '/jvpkBenB6hv19WWYVlaiow8zklq.jpg'),
('1234731', 'Anaconda', 2025, 'Tom Gormican', 'A group of friends facing mid-life crises head to the rainforest with the intention of remaking their favorite movie from their youth, only to find themselves in a fight for their lives against natural disasters, giant snakes and violent criminals.', '/hBxN6dwrANN1ic3a4G9x6JZcR3C.jpg', '/swxhEJsAWms6X1fDZ4HdbvYBSf9.jpg'),
('698687', 'Transformers One', 2024, 'Josh Cooley', 'The untold origin story of Optimus Prime and Megatron, better known as sworn enemies, but once were friends bonded like brothers who changed the fate of Cybertron forever.', '/iRCgqpdVE4wyLQvGYU3ZP7pAtUc.jpg', '/cMfokHWle5lfCreoV08cbmkKv6G.jpg'),
('383498', 'Deadpool 2', 2018, 'David Leitch', 'Wisecracking mercenary Deadpool battles the evil and powerful Cable and other bad guys to save a boy''s life.', '/to0spRl1CMDvyUbOnbb4fTk3VAd.jpg', '/3P52oz9HPQWxcwHOwxtyrVV1LKi.jpg'),
('744', 'Top Gun', 1986, 'Tony Scott', 'For Lieutenant Pete ''Maverick'' Mitchell and his friend and co-pilot Nick ''Goose'' Bradshaw, being accepted into an elite training school for fighter pilots is a dream come true. But a tragedy, as well as personal demons, will threaten Pete''s dreams of becoming an ace pilot.', '/xUuHj3CgmZQ9P2cMaqQs4J0d4Zc.jpg', '/dBgxEkWe17R0AJDAvAhpeVELQx2.jpg'),
('1495', 'Kingdom of Heaven', 2005, 'Ridley Scott', 'After his wife dies, a blacksmith named Balian is thrust into royalty, political intrigue and bloody holy wars during the Crusades.', '/rNaBe4TwbMef71sgscqabpGKsxh.jpg', '/8itHQecANtOevcCdr3AhVxFCYkw.jpg'),
('216015', 'Fifty Shades of Grey', 2015, 'Sam Taylor-Johnson', 'When college senior Anastasia Steele steps in for her sick roommate to interview prominent businessman Christian Grey for their campus paper, little does she realize the path her life will take. Christian, as enigmatic as he is rich and powerful, finds himself strangely drawn to Ana, and she to him. Though sexually inexperienced, Ana plunges headlong into an affair -- and learns that Christian''s true sexual proclivities push the boundaries of pain and pleasure.', '/63kGofUkt1Mx0SIL4XI4Z5AoSgt.jpg', '/7IGKrY1f1KfwMipx9wZC4NRgIdF.jpg'),
('545611', 'Everything Everywhere All at Once', 2022, 'Daniel Scheinert, Daniel Kwan', 'An aging Chinese immigrant is swept up in an insane adventure, where she alone can save what''s important to her by connecting with the lives she could have led in other universes.', '/u68AjlvlutfEIcpmbYpKcdi09ut.jpg', '/ss0Os3uWJfQAENILHZUdX8Tt1OC.jpg'),
('135397', 'Jurassic World', 2015, 'Colin Trevorrow', 'Twenty-two years after the events of Jurassic Park, Isla Nublar now features a fully functioning dinosaur theme park, Jurassic World, as originally envisioned by John Hammond.', '/rhr4y79GpxQF9IsfJItRXVaoGs4.jpg', '/dF6FjTZzRTENfB4R17HDN20jLT2.jpg'),
('337167', 'Fifty Shades Freed', 2018, 'James Foley', 'Believing they have left behind shadowy figures from their past, newlyweds Christian and Ana fully embrace an inextricable connection and shared life of luxury. But just as she steps into her role as Mrs. Grey and he relaxes into an unfamiliar stability, new threats could jeopardize their happy ending before it even begins.', '/jjPJ4s3DWZZvI4vw8Xfi4Vqa1Q8.jpg', '/9ywA15OAiwjSTvg3cBs9B7kOCBF.jpg'),
('1236153', 'Mercy', 2026, 'Timur Bekmambetov', 'In the near future, a detective stands on trial accused of murdering his wife. He has ninety minutes to prove his innocence to the advanced AI Judge he once championed, before it determines his fate.', '/pyok1kZJCfyuFapYXzHcy7BLlQa.jpg', '/gIClklFGYBe0uiOoiP2vtocJbss.jpg'),
('425274', 'Now You See Me: Now You Don''t', 2025, 'Ruben Fleischer', 'The original Four Horsemen reunite with a new generation of illusionists to take on powerful diamond heiress Veronika Vanderberg, who leads a criminal empire built on money laundering and trafficking. The new and old magicians must overcome their differences to work together on their most ambitious heist yet.', '/oD3Eey4e4Z259XLm3eD3WGcoJAh.jpg', '/ufqytAlziHq5pljKByGJ8IKhtEZ.jpg'),
('429', 'The Good, the Bad and the Ugly', 1966, 'Sergio Leone', 'While the Civil War rages on between the Union and the Confederacy, three men – a quiet loner, a ruthless hitman, and a Mexican bandit – comb the American Southwest in search of a strongbox containing $200,000 in stolen gold.', '/bX2xnavhMYjWDoZp1VM6VnU1xwe.jpg', '/x4biAVdPVCghBlsVIzB6NmbghIz.jpg'),
('111', 'Scarface', 1983, 'Brian De Palma', 'After getting a green card in exchange for assassinating a Cuban government official, Tony Montana stakes a claim on the drug trade in Miami. Viciously murdering anyone who stands in his way, Tony eventually becomes the biggest drug lord in the state, controlling nearly all the cocaine that comes through Miami. But increased pressure from the police, wars with Colombian drug cartels and his own drug-fueled paranoia serve to fuel the flames of his eventual downfall.', '/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg', '/1qM2BYNE11Viby8ImC9LC00DgDr.jpg'),
('519182', 'Despicable Me 4', 2024, 'Chris Renaud', 'Gru and Lucy and their girls—Margo, Edith and Agnes—welcome a new member to the Gru family, Gru Jr., who is intent on tormenting his dad. Gru also faces a new nemesis in Maxime Le Mal and his femme fatale girlfriend Valentina, forcing the family to go on the run.', '/wWba3TaojhK7NdycRhoQpsG0FaH.jpg', '/twsxsfao6ZOVvT8LfudH603MMi6.jpg'),
('701387', 'Bugonia', 2025, 'Yorgos Lanthimos', 'Two conspiracy obsessed young men kidnap the high-powered CEO of a major company, convinced that she is an alien intent on destroying planet Earth.', '/rSdOua3wKMEaFWDcKAYWRjXQWOt.jpg', '/tN3pTxkQoP96wtaEahYuRVdUWb2.jpg'),
('1072790', 'Anyone but You', 2023, 'Will Gluck', 'After an amazing first date, Bea and Ben’s fiery attraction turns ice cold — until they find themselves unexpectedly reunited at a destination wedding in Australia. So they do what any two mature adults would do: pretend to be a couple.', '/5qHoazZiaLe7oFBok7XlUhg96f2.jpg', '/j9eOeLlTGoHoM8BNUJVNyWmIvCi.jpg'),
('315162', 'Puss in Boots: The Last Wish', 2022, 'Joel Crawford', 'Puss in Boots discovers that his passion for adventure has taken its toll: He has burned through eight of his nine lives, leaving him with only one life left. Puss sets out on an epic journey to find the mythical Last Wish and restore his nine lives.', '/kuf6dutpsT0vSVehic3EZIqkOBt.jpg', '/jr8tSoJGj33XLgFBy6lmZhpGQNu.jpg'),
('1151031', 'Bring Her Back', 2025, 'Danny Philippou, Michael Philippou', 'Following the death of their father, a brother and sister are sent to live with a foster mother, only to learn that she is hiding a terrifying secret.', '/fp4PvxoWb9bwsvInicJPXByj4CS.jpg', '/2IIKts2A9vnUdM9tTC76B8tDmuZ.jpg'),
('572802', 'Aquaman and the Lost Kingdom', 2023, 'James Wan', 'Black Manta seeks revenge on Aquaman for his father''s death. Wielding the Black Trident''s power, he becomes a formidable foe. To defend Atlantis, Arthur (Aquaman) forges an alliance with his imprisoned brother. They must protect the kingdom.', '/7lTnXOy0iNtBAdRP3TZvaKJ77F6.jpg', '/bckxSN9ueOgm0gJpVJmPQrecWul.jpg'),
('285', 'Pirates of the Caribbean: At World''s End', 2007, 'Gore Verbinski', 'After losing Captain Jack Sparrow to the locker of Davy Jones, Will Turner, Elizabeth Swann, and Captain Barbossa journey to the ends of the earth to rescue him. And as the East India Trading Company tightens its grip on the seas under Lord Cutler Beckett—now in control of Davy Jones—the fate of piracy hangs by a thread. Now, they must unite the pirate lords for one final stand. But as loyalties are tested and alliances shift, each must ultimately choose where they stand in the battle for freedom on the high seas.', '/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg', '/1jHxkVXMI5s3vRiyiZooUy1shB5.jpg'),
('637649', 'Wrath of Man', 2021, 'Guy Ritchie', 'A cold and mysterious new security guard for a Los Angeles cash truck company surprises his co-workers when he unleashes precision skills during a heist. The crew is left wondering who he is and where he came from. Soon, the marksman''s ultimate motive becomes clear as he takes dramatic and irrevocable steps to settle a score.', '/M7SUK85sKjaStg4TKhlAVyGlz3.jpg', '/70AV2Xx5FQYj20labp0EGdbjI6E.jpg'),
('1156593', 'Your Fault', 2024, 'Domingo González', 'The love between Noah and Nick seems unwavering despite their parents'' attempts to separate them. But his job and her entry into college open up their lives to new relationships that will shake the foundations of both their relationship and the Leister family itself.', '/1sQA7lfcF9yUyoLYC0e6Zo3jmxE.jpg', '/k24eZq5I3jyz4htPkZCRpnUmBzE.jpg'),
('2105', 'American Pie', 1999, 'Paul Weitz', 'At a high-school party, four friends find that losing their collective virginity isn''t as easy as they had thought. But they still believe that they need to do so before college. To motivate themselves, they enter a pact to all "score" by their senior prom.', '/5P68by2Thn8wHAziyWGEw2O7hco.jpg', '/z9DFGaWj4G4kZUWLZ6ESs1NP1Fp.jpg'),
('980477', 'Ne Zha 2', 2025, 'Jiao Zi', 'After a catastrophic event leaves their bodies destroyed, Ne Zha and Ao Bing are granted a fragile second chance at life. As tensions rise between the dragon clans and celestial forces, the two must undergo a series of perilous trials that will test their bond, challenge their identities, and decide the fate of both mortals and immortals.', '/293Mo4GWf7Tl0TfAr5NFghqeMy7.jpg', '/c9xmB53umjnrCMS4pZz11clF3yJ.jpg'),
('381284', 'Hidden Figures', 2016, 'Theodore Melfi', 'The untold story of Katherine G. Johnson, Dorothy Vaughan and Mary Jackson – brilliant African-American women working at NASA and serving as the brains behind one of the greatest operations in history – the launch of astronaut John Glenn into orbit. The visionary trio crossed all gender and race lines to inspire generations to dream big.', '/9lfz2W2uGjyow3am00rsPJ8iOyq.jpg', '/rfkIeCaIHhN3K5wjJJqKmfUjYp8.jpg'),
('333339', 'Ready Player One', 2018, 'Steven Spielberg', 'When the creator of a popular video game system dies, a virtual contest is created to compete for his fortune.', '/pU1ULUq8D3iRxl1fdX2lZIzdHuI.jpg', '/5a7lMDn3nAj2ByO0X1fg6BhUphR.jpg'),
('181808', 'Star Wars: The Last Jedi', 2017, 'Rian Johnson', 'Rey develops her newly discovered abilities with the guidance of Luke Skywalker, who is unsettled by the strength of her powers. Meanwhile, the Resistance prepares to do battle with the First Order.', '/ySaaKHOLAQU5HoZqWmzDIj1VvZ1.jpg', '/bIUaCtWaRgd78SnoHJDI8TNf7Sd.jpg'),
('866398', 'The Beekeeper', 2024, 'David Ayer', 'One man''s campaign for vengeance takes on national stakes after he is revealed to be a former operative of a powerful and clandestine organization known as Beekeepers.', '/A7EByudX0eOzlkQ2FIbogzyazm2.jpg', '/f0ACHVpV707zqu4etZrXnWNdSgL.jpg'),
('1084187', 'Pretty Lethal', 2026, 'Vicky Jewson', 'A troupe of ballerinas find themselves fighting for survival as they attempt to escape from a remote inn after their bus breaks down on the way to a dance competition.', '/znTPnXCK3lEQJgqXCvP7e5FUz6f.jpg', '/z3bzhmC0CPikWeerUkLO73YvGrC.jpg'),
('786892', 'Furiosa: A Mad Max Saga', 2024, 'George Miller', 'As the world falls, young Furiosa is snatched from the Green Place of Many Mothers into the hands of a great biker horde led by the warlord Dementus. Sweeping through the wasteland, they encounter the citadel presided over by Immortan Joe. The two tyrants wage war for dominance, and Furiosa must survive many trials as she puts together the means to find her way home.', '/iADOJ8Zymht2JPMoy3R7xceZprc.jpg', '/raph7qjAGTMXaIjVxt6ZDSXRzUr.jpg'),
('629', 'The Usual Suspects', 1995, 'Bryan Singer', 'Held in an L.A. interrogation room, Verbal Kint attempts to convince the feds that a mythic crime lord, Keyser Soze, not only exists, but was also responsible for drawing him and his four partners into a multi-million dollar heist that ended with an explosion in San Pedro harbor – leaving few survivors. Verbal lures his interrogators with an incredible story of the crime lord''s almost supernatural prowess.', '/99X2SgyFunJFXGAYnDv3sb9pnUD.jpg', '/hy0Hx9fMPk2fmw26Li60z1S2giU.jpg'),
('320288', 'Dark Phoenix', 2019, 'Simon Kinberg', 'The X-Men face their most formidable and powerful foe when one of their own, Jean Grey, starts to spiral out of control. During a rescue mission in outer space, Jean is nearly killed when she''s hit by a mysterious cosmic force. Once she returns home, this force not only makes her infinitely more powerful, but far more unstable. The X-Men must now band together to save her soul and battle aliens that want to use Grey''s new abilities to rule the galaxy.', '/cCTJPelKGLhALq3r51A9uMonxKj.jpg', '/cjRUhKyt2Jo3V1KNzc5tpPNfccG.jpg'),
('758009', 'Shotgun Wedding', 2022, 'Jason Moore', 'Darcy and Tom gather their families for the ultimate destination wedding but when the entire party is taken hostage, “’Til Death Do Us Part” takes on a whole new meaning. Now, Darcy and Tom must save their loved ones—if they don’t kill each other first.', '/t79ozwWnwekO0ADIzsFP1E5SkvR.jpg', '/zGoZB4CboMzY1z4G3nU6BWnMDB2.jpg'),
('566525', 'Shang-Chi and the Legend of the Ten Rings', 2021, 'Destin Daniel Cretton', 'Shang-Chi must confront the past he thought he left behind when he is drawn into the web of the mysterious Ten Rings organization.', '/9f2Q0U3IOsLgrI2HkvldwSABZy5.jpg', '/r7K6Xt0RX4Mw0cAbZVw5cyb1Tux.jpg'),
('4348', 'Pride & Prejudice', 2005, 'Joe Wright', 'A story of love and life among the landed English gentry during the Georgian era. Mr. Bennet is a gentleman living in Hertfordshire with his overbearing wife and five daughters, but if he dies their house will be inherited by a distant cousin whom they have never met, so the family''s future happiness and security is dependent on the daughters making good marriages.', '/o8UhmEbWPHmTUxP0lMuCoqNkbB3.jpg', '/1Onam6oWyFAUCcoxtdWkACtEiNr.jpg'),
('1734', 'The Mummy Returns', 2001, 'Stephen Sommers', 'Rick and Evelyn O’Connell, along with their 8-year-old son Alex, discover the key to the legendary Scorpion King’s might: the fabled Bracelet of Anubis. Unfortunately, a newly resurrected Imhotep has designs on the bracelet as well, and isn’t above kidnapping its new bearer, Alex, to gain control of Anubis’s otherworldly army.', '/kdJsW7hcy1lrj7tdMPycTAQPAiR.jpg', '/7s7WkAFPBsMTprYMbqbgKoppQsR.jpg'),
('823219', 'Flow', 2024, 'Gints Zilbalodis', 'A solitary cat, displaced by a great flood, finds refuge on a boat with various species and must navigate the challenges of adapting to a transformed world together.', '/z2sG41PxfL1hnL1mHbxzSREUtOf.jpg', '/4XPNNt0zfZKBqxxVWaQALd57UHl.jpg'),
('562', 'Die Hard', 1988, 'John McTiernan', 'High above the city of L.A. a team of terrorists has seized a building, taken hostages, and declared war. One man has manages to escape... An off-duty cop hiding somewhere inside. He''s alone, tired... and the only chance anyone has got.', '/7Bjd8kfmDSOzpmhySpEhkUyK2oH.jpg', '/bvk2AAH64lP2YZs02Q3jskfHT8j.jpg'),
('101', 'Léon: The Professional', 1994, 'Luc Besson', 'Léon, the top hit man in New York, has earned a rep as an effective "cleaner". But when his next-door neighbors are wiped out by a loose-cannon DEA agent, he becomes the unwilling custodian of 12-year-old Mathilda. Before long, Mathilda''s thoughts turn to revenge, and she considers following in Léon''s footsteps.', '/bxB2q91nKYp8JNzqE7t7TWBVupB.jpg', '/fj0hwDJEOOHllRim2BMt5L7tbjf.jpg'),
('1064213', 'Anora', 2024, 'Sean Baker', 'A young sex worker from Brooklyn gets her chance at a Cinderella story when she meets and impulsively marries the son of an oligarch. Once the news reaches Russia, her fairytale is threatened as his parents set out to get the marriage annulled.', '/cgXk2tNYhJZLXdBDO5DidAVzQ82.jpg', '/qvyOfwTC3qdbzkqdXWSSEMHtjBZ.jpg'),
('1315303', 'Primate', 2026, 'Johannes Roberts', 'College student Lucy and her friends spend their vacation at her family''s home in Hawaii, which includes her pet chimpanzee, Ben. However, when Ben contracts rabies after being bitten by a rabid animal, the group must fight for their lives in order to avoid the now-violent chimp.', '/rKleYiEj4pFqxedTRWfujLooi84.jpg', '/d5C5Wsx4fnMRA0tj9BK1kTPcgQe.jpg'),
('679', 'Aliens', 1986, 'James Cameron', 'Ripley, the sole survivor of the Nostromo''s deadly encounter with the monstrous Alien, returns to Earth after drifting through space in hypersleep for 57 years. Although her story is initially met with skepticism, she agrees to accompany a team of Colonial Marines back to LV-426.', '/r1x5JGpyqZU8PYhbs4UcrO1Xb6x.jpg', '/4kix6fAblJIH6eMs0Ku2loyZJXK.jpg'),
('87101', 'Terminator Genisys', 2015, 'Alan Taylor', 'The year is 2029. John Connor, leader of the resistance continues the war against the machines. At the Los Angeles offensive, John''s fears of the unknown future begin to emerge when TECOM spies reveal a new plot by SkyNet that will attack him from both fronts; past and future, and will ultimately change warfare forever.', '/oZRVDpNtmHk8M1VYy1aeOWUXgbC.jpg', '/wvlIoof1FnKPLv9jAYanuP31V0C.jpg'),
('694', 'The Shining', 1980, 'Stanley Kubrick', 'Jack Torrance accepts a caretaker job at the Overlook Hotel, where he, along with his wife Wendy and their son Danny, must live isolated from the rest of the world for the winter. But they aren''t prepared for the madness that lurks within.', '/uAR0AWqhQL1hQa69UDEbb2rE5Wx.jpg', '/AdKA2F1SzYPhSZdEbjH1Zh75UVQ.jpg'),
('141052', 'Justice League', 2017, 'Zack Snyder, Joss Whedon', 'Fuelled by his restored faith in humanity and inspired by Superman''s selfless act, Bruce Wayne and Diana Prince assemble a team of metahumans consisting of Barry Allen, Arthur Curry and Victor Stone to face the catastrophic threat of Steppenwolf and the Parademons who are on the hunt for three Mother Boxes on Earth.', '/eifGNCSDuxJeS1loAXil5bIGgvC.jpg', '/2nyaeISu2xIxIgZYNpX4UayY8PN.jpg'),
('1097549', 'Babygirl', 2024, 'Halina Reijn', 'A high-powered CEO puts her career and family on the line when she begins a torrid affair with her much younger intern.', '/ilwO6elz3mLV9CToT7C8pjVeKX0.jpg', '/s7vWRjcfRVMW8tBIxhC3UhKxRoo.jpg'),
('296096', 'Me Before You', 2016, 'Thea Sharrock', 'Lou Clark, a directionless 26-year-old from the English countryside, takes a job at the local castle as a caregiver and companion to a wealthy young banker, Will Traynor. Wheelchair-bound from an accident two years prior, the once adventurous Will has all but given up — that is until Lou determines to show him that life is worth living.', '/Ia3dzj5LnCj1ZBdlVeJrbKJQxG.jpg', '/3WK7p9EdZmmvB1IbB2Vw9Rf4lXH.jpg'),
('696506', 'Mickey 17', 2025, 'Bong Joon Ho', 'Unlikely hero Mickey Barnes finds himself in the extraordinary circumstance of working for an employer who demands the ultimate commitment to the job… to die, for a living.', '/edKpE9B5qN3e559OuMCLZdW1iBZ.jpg', '/9PRKAdrDvAdCfg3EcApLTfzGsEt.jpg'),
('976573', 'Elemental', 2023, 'Peter Sohn', 'In a city where fire, water, land and air residents live together, a fiery young woman and a go-with-the-flow guy will discover something elemental: how much they have in common.', '/4Y1WNkd88JXmGfhtWR7dmDAo1T2.jpg', '/4fLZUr1e65hKPPVw0R3PmKFKxj1.jpg'),
('82690', 'Wreck-It Ralph', 2012, 'Rich Moore', 'Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game''s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero''s Duty, a first-person shooter where he helps the game''s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.', '/nrEupcBwf4O1zihCM34NoXusZDq.jpg', '/3IFRjBDwtk0DlIsDfJ2zEzLjUBi.jpg'),
('1125257', 'Freakier Friday', 2025, 'Nisha Ganatra', 'Years after Tess and Anna endured an identity crisis, Anna now has a daughter of her own and a soon-to-be stepdaughter. As they navigate the myriad challenges that come when two families merge, Tess and Anna discover lightning might indeed strike twice.', '/9wV65OmsjLAqBfDnYTkMPutXH8j.jpg', '/yQy9Y3p5INwkfTuHSnzYnz4MCV3.jpg'),
('396535', 'Train to Busan', 2016, 'Yeon Sang-ho', 'When a zombie virus pushes Korea into a state of emergency, those trapped on an express train to Busan must fight for their own survival.', '/vNVFt6dtcqnI7hqa6LFBUibuFiw.jpg', '/brnfCYyz8EMbBrHgmh8sCwBi5i1.jpg'),
('181812', 'Star Wars: The Rise of Skywalker', 2019, 'J.J. Abrams', 'The surviving Resistance faces the First Order once again as the journey of Rey, Finn and Poe Dameron continues. With the power and knowledge of generations behind them, the final battle begins.', '/db32LaOibwEliAmSL2jjDF6oDdj.jpg', '/jOzrELAzFxtMx2I4uDGHOotdfsS.jpg'),
('9502', 'Kung Fu Panda', 2008, 'Mark Osborne, John Stevenson', 'Chosen by prophecy but doubted by all, Po is an unlikely choice for the mystical title of the Dragon Warrior—a clumsy panda thrust into the world of kung fu as a deadly enemy threatens the Valley of Peace. Under reluctant guidance by Master Shifu and the Furious Five, Po must embrace who he is to unlock the power that no scroll can teach.', '/wWt4JYXTg5Wr3xBW2phBrMKgp3x.jpg', '/qdthf9WrRDSaIkGVQGhhJ9pz1hn.jpg'),
('667538', 'Transformers: Rise of the Beasts', 2023, 'Steven Caple Jr.', 'When a new threat capable of destroying the entire planet emerges, Optimus Prime and the Autobots must team up with a powerful faction known as the Maximals. With the fate of humanity hanging in the balance, humans Noah and Elena will do whatever it takes to help the Transformers as they engage in the ultimate battle to save Earth.', '/gPbM0MK8CP8A174rmUwGsADNYKD.jpg', '/2vFuG6bWGyQUzYS9d69E5l85nIz.jpg'),
('920', 'Cars', 2006, 'John Lasseter', 'Lightning McQueen, a hotshot rookie race car driven to succeed, discovers that life is about the journey, not the finish line, when he finds himself unexpectedly detoured in the sleepy Route 66 town of Radiator Springs. On route across the country to the big Piston Cup Championship in California to compete against two seasoned pros, McQueen gets to know the town''s offbeat characters.', '/2Touk3m5gzsqr1VsvxypdyHY5ci.jpg', '/sOLgkBKf1gjMRc4yXxM5aciXdfr.jpg');
